// 자동 생성 파일 — tools/build_grammar.py 로 다시 만든다
window.GRAMMAR = [{"id":"g01","lv":1,"title":"是 — A는 B이다","tag":"是字句","point":"'A는 B이다'라고 말할 때 是를 써요. 부정은 不是예요. 형용사 앞에는 是를 쓰지 않아요 (我很忙 ○ / 我是忙 ✕).","pattern":["A + 是 + B","A + 不是 + B"],"ex":[{"zh":"我是学生。","py":"Wǒ shì xuéshēng.","ko":"나는 학생이야."},{"zh":"他不是中国人。","py":"Tā bú shì Zhōngguó rén.","ko":"그는 중국 사람이 아니야."},{"zh":"这是我的书。","py":"Zhè shì wǒ de shū.","ko":"이건 내 책이야."}],"qs":[{"type":"fill","zh":"她＿＿我姐姐。","choices":["是","有","在","很"],"answer":"是","full":{"zh":"她是我姐姐。","py":"Tā shì wǒ jiějie.","ko":"그녀는 우리 언니야."},"why":"'A는 B이다'는 是예요."},{"type":"pick","ko":"나 바빠.","choices":["我很忙。","我是忙。","我是很忙。"],"answer":"我很忙。","full":{"zh":"我很忙。","py":"Wǒ hěn máng.","ko":"나 바빠."},"why":"형용사(忙) 앞에는 是 대신 很을 써요."},{"type":"fill","zh":"他们都＿＿老师。","ko":"그들은 모두 선생님이야.","choices":["是","有","很","在"],"answer":"是","full":{"zh":"他们都是老师。","py":"Tāmen dōu shì lǎoshī.","ko":"그들은 모두 선생님이야."},"why":"'A는 B이다'는 是. 都는 是 앞에 와요."},{"type":"pick","ko":"이건 내 휴대폰이 아니야.","choices":["这不是我的手机。","这没是我的手机。","这是不我的手机。"],"answer":"这不是我的手机。","full":{"zh":"这不是我的手机。","py":"Zhè bú shì wǒ de shǒujī.","ko":"이건 내 휴대폰이 아니야."},"why":"是의 부정은 不是예요 (没是 ✕)."}]},{"id":"g02","lv":1,"title":"有 — 있다 · 가지고 있다","tag":"有字句","point":"'~이 있다, ~을 가지고 있다'는 有예요. 부정은 没有예요 (不有 ✕). '장소 + 有 + 사물'은 '~에 …이 있다'예요.","pattern":["A + 有 + B","A + 没有 + B","장소 + 有 + 수량 + 사물"],"ex":[{"zh":"我有一个弟弟。","py":"Wǒ yǒu yí ge dìdi.","ko":"나는 남동생이 한 명 있어."},{"zh":"我没有电脑。","py":"Wǒ méiyǒu diànnǎo.","ko":"나는 컴퓨터가 없어."},{"zh":"桌子上有两个杯子。","py":"Zhuōzi shang yǒu liǎng ge bēizi.","ko":"책상 위에 컵이 두 개 있어."}],"qs":[{"type":"fill","zh":"我＿＿哥哥。","ko":"나는 형이 없어.","choices":["没有","不有","不是","不"],"answer":"没有","full":{"zh":"我没有哥哥。","py":"Wǒ méiyǒu gēge.","ko":"나는 형이 없어."},"why":"有의 부정은 不有가 아니라 没有예요."},{"type":"fill","zh":"教室里＿＿很多学生。","ko":"교실에 학생이 많이 있어.","choices":["有","是","在","很"],"answer":"有","full":{"zh":"教室里有很多学生。","py":"Jiàoshì li yǒu hěn duō xuéshēng.","ko":"교실에 학생이 많이 있어."},"why":"'장소 + 有 + 사물' = ~에 …이 있다."},{"type":"pick","ko":"우리 집에는 고양이가 한 마리 있어.","choices":["我家有一只猫。","我家是一只猫。","我家在一只猫。"],"answer":"我家有一只猫。","full":{"zh":"我家有一只猫。","py":"Wǒ jiā yǒu yì zhī māo.","ko":"우리 집에는 고양이가 한 마리 있어."},"why":"'장소 + 有 + 수량 + 사물' = ~에 …이 있다."},{"type":"fill","zh":"你＿＿没有姐姐？","ko":"너 언니 있어?","choices":["有","是","在","要"],"answer":"有","full":{"zh":"你有没有姐姐？","py":"Nǐ yǒu méiyǒu jiějie?","ko":"너 언니 있어?"},"why":"有没有 = 있어 없어? (긍정 + 부정으로 묻기)"}]},{"id":"g03","lv":1,"title":"很 · 太…了 · 有点儿 — 형용사 문장","tag":"形容词谓语句","point":"형용사는 是 없이 바로 '~하다'가 돼요. 보통 很을 붙여요(가볍게 '~해'). 太…了는 '너무 ~하다', 有点儿은 '좀 ~하다'(주로 불만), 非常은 '매우'예요.","pattern":["주어 + 很 + 형용사","太 + 형용사 + 了","有点儿 + 형용사"],"ex":[{"zh":"今天很冷。","py":"Jīntiān hěn lěng.","ko":"오늘 추워."},{"zh":"这个太贵了！","py":"Zhège tài guì le!","ko":"이거 너무 비싸!"},{"zh":"我有点儿累。","py":"Wǒ yǒudiǎnr lèi.","ko":"나 좀 피곤해."}],"qs":[{"type":"fill","zh":"这件衣服太大＿＿。","ko":"이 옷 너무 커.","choices":["了","的","吗","很"],"answer":"了","full":{"zh":"这件衣服太大了。","py":"Zhè jiàn yīfu tài dà le.","ko":"이 옷 너무 커."},"why":"'너무 ~하다'는 太 + 형용사 + 了."},{"type":"pick","ko":"오늘 좀 더워. (불만)","choices":["今天有点儿热。","今天一点儿热。","今天热有点儿。"],"answer":"今天有点儿热。","full":{"zh":"今天有点儿热。","py":"Jīntiān yǒudiǎnr rè.","ko":"오늘 좀 더워."},"why":"형용사 앞에는 有点儿을 써요. 一点儿은 형용사 뒤나 명사 앞에 와요."},{"type":"fill","zh":"这个苹果＿＿大。","ko":"이 사과 정말 크다.","choices":["真","是","有","了"],"answer":"真","full":{"zh":"这个苹果真大。","py":"Zhège píngguǒ zhēn dà.","ko":"이 사과 정말 크다."},"why":"형용사 앞에 真 = 정말 ~하다. 是는 쓰지 않아요."},{"type":"pick","ko":"오늘 날씨 아주 좋다.","choices":["今天天气很好。","今天天气是好。","今天是天气好。"],"answer":"今天天气很好。","full":{"zh":"今天天气很好。","py":"Jīntiān tiānqì hěn hǎo.","ko":"오늘 날씨 아주 좋다."},"why":"형용사 문장에는 是 대신 很을 써요."}]},{"id":"g04","lv":1,"title":"吗 — 예/아니오 질문","tag":"是非问句","point":"평서문 끝에 吗만 붙이면 '예/아니오'로 답하는 질문이 돼요. 什么·谁·哪儿 같은 의문사가 있는 질문에는 吗를 붙이지 않아요.","pattern":["평서문 + 吗？"],"ex":[{"zh":"你是老师吗？","py":"Nǐ shì lǎoshī ma?","ko":"당신은 선생님이에요?"},{"zh":"你喜欢喝茶吗？","py":"Nǐ xǐhuan hē chá ma?","ko":"너 차 마시는 거 좋아해?"},{"zh":"明天你来吗？","py":"Míngtiān nǐ lái ma?","ko":"내일 너 와?"}],"qs":[{"type":"fill","zh":"你是中国人＿＿？","ko":"너 중국 사람이야?","choices":["吗","的","了","也"],"answer":"吗","full":{"zh":"你是中国人吗？","py":"Nǐ shì Zhōngguó rén ma?","ko":"너 중국 사람이야?"},"why":"예/아니오 질문은 문장 끝에 吗."},{"type":"pick","ko":"너 이름이 뭐야?","choices":["你叫什么名字？","你叫什么名字吗？","你叫吗什么名字？"],"answer":"你叫什么名字？","full":{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","ko":"너 이름이 뭐야?"},"why":"什么가 있는 질문에는 吗를 붙이지 않아요."},{"type":"fill","zh":"你认识他＿＿？","ko":"너 그 사람 알아?","choices":["吗","呢","的","了"],"answer":"吗","full":{"zh":"你认识他吗？","py":"Nǐ rènshi tā ma?","ko":"너 그 사람 알아?"},"why":"예/아니오 질문은 끝에 吗."},{"type":"pick","ko":"너 어디 가?","choices":["你去哪儿？","你去哪儿吗？","你哪儿去吗？"],"answer":"你去哪儿？","full":{"zh":"你去哪儿？","py":"Nǐ qù nǎr?","ko":"너 어디 가?"},"why":"哪儿 같은 의문사가 있으면 吗를 붙이지 않아요."}]},{"id":"g05","lv":1,"title":"什么 · 谁 · 哪儿 · 几 · 多少 — 의문사","tag":"特指问句","point":"묻고 싶은 자리에 의문사를 그대로 넣어요. 어순은 평서문과 같아요. 几는 10 이하로 예상될 때, 多少는 수에 상관없이 써요.","pattern":["你去哪儿？ ← 我去学校。","几 + 양사 + 명사","多少 + (양사) + 명사"],"ex":[{"zh":"你去哪儿？","py":"Nǐ qù nǎr?","ko":"너 어디 가?"},{"zh":"他是谁？","py":"Tā shì shéi?","ko":"그 사람 누구야?"},{"zh":"这个多少钱？","py":"Zhège duōshao qián?","ko":"이거 얼마야?"}],"qs":[{"type":"fill","zh":"你去＿＿？我去学校。","ko":"너 어디 가? 나 학교 가.","choices":["哪儿","什么","谁","几"],"answer":"哪儿","full":{"zh":"你去哪儿？我去学校。","py":"Nǐ qù nǎr? Wǒ qù xuéxiào.","ko":"너 어디 가? 나 학교 가."},"why":"장소를 물을 때는 哪儿."},{"type":"fill","zh":"这本书＿＿钱？","ko":"이 책 얼마야?","choices":["多少","几","什么","怎么"],"answer":"多少","full":{"zh":"这本书多少钱？","py":"Zhè běn shū duōshao qián?","ko":"이 책 얼마야?"},"why":"값은 多少钱. 几는 바로 뒤에 양사가 와야 해요(几块钱)."},{"type":"fill","zh":"＿＿是你的老师？","ko":"누가 너희 선생님이야?","choices":["谁","什么","哪儿","几"],"answer":"谁","full":{"zh":"谁是你的老师？","py":"Shéi shì nǐ de lǎoshī?","ko":"누가 너희 선생님이야?"},"why":"사람을 물을 때는 谁."},{"type":"fill","zh":"你有＿＿个孩子？","ko":"너 아이가 몇 명이야?","choices":["几","什么","谁","哪儿"],"answer":"几","full":{"zh":"你有几个孩子？","py":"Nǐ yǒu jǐ ge háizi?","ko":"너 아이가 몇 명이야?"},"why":"적은 수를 물을 때는 几 + 양사."}]},{"id":"g06","lv":1,"title":"你去不去？ — 긍정 + 부정 질문","tag":"正反问句","point":"동사나 형용사의 긍정과 부정을 이어 붙이면 질문이 돼요. 이때는 吗를 붙이지 않아요. 가운데 不는 가볍게(경성) 읽어요.","pattern":["동사 + 不 + 동사","형용사 + 不 + 형용사"],"ex":[{"zh":"你去不去？","py":"Nǐ qù bu qù?","ko":"너 갈 거야 안 갈 거야?"},{"zh":"这个菜好吃不好吃？","py":"Zhège cài hǎochī bu hǎochī?","ko":"이 요리 맛있어?"},{"zh":"你是不是学生？","py":"Nǐ shì bu shì xuéshēng?","ko":"너 학생 맞아?"}],"qs":[{"type":"fill","zh":"明天你来＿＿来？","ko":"내일 너 올 거야 안 올 거야?","choices":["不","没","吗","也"],"answer":"不","full":{"zh":"明天你来不来？","py":"Míngtiān nǐ lái bu lái?","ko":"내일 너 올 거야 안 올 거야?"},"why":"긍정 + 不 + 긍정으로 묻는 질문이에요."},{"type":"pick","ko":"너 바빠?","choices":["你忙不忙？","你忙不忙吗？","你不忙忙？"],"answer":"你忙不忙？","full":{"zh":"你忙不忙？","py":"Nǐ máng bu máng?","ko":"너 바빠?"},"why":"긍정+부정 질문에는 吗를 붙이지 않아요."},{"type":"fill","zh":"你喜欢不＿＿中国菜？","ko":"너 중국 요리 좋아해?","choices":["喜欢","喜","吗","也"],"answer":"喜欢","full":{"zh":"你喜欢不喜欢中国菜？","py":"Nǐ xǐhuan bu xǐhuan Zhōngguó cài?","ko":"너 중국 요리 좋아해?"},"why":"不 뒤에 동사를 그대로 한 번 더 (喜欢不喜欢)."},{"type":"pick","ko":"이거 비싸?","choices":["这个贵不贵？","这个贵不贵吗？","这个不贵贵？"],"answer":"这个贵不贵？","full":{"zh":"这个贵不贵？","py":"Zhège guì bu guì?","ko":"이거 비싸?"},"why":"형용사도 긍정 + 不 + 긍정으로 물어요. 吗는 붙이지 않아요."}]},{"id":"g07","lv":1,"title":"不 vs 没(有) — 두 가지 부정","tag":"否定副词","point":"不는 지금·앞으로 안 함, 습관, 의지, 형용사의 부정이에요. 没(有)는 '(과거에) 안 했다'와 '없다'예요. 没(有) 문장에는 了를 붙이지 않아요.","pattern":["不 + 동사/형용사 (안 한다·아니다)","没(有) + 동사 (안 했다)"],"ex":[{"zh":"我明天不去。","py":"Wǒ míngtiān bú qù.","ko":"나 내일 안 가."},{"zh":"我昨天没去。","py":"Wǒ zuótiān méi qù.","ko":"나 어제 안 갔어."},{"zh":"我不喜欢吃肉。","py":"Wǒ bù xǐhuan chī ròu.","ko":"나는 고기 안 좋아해."}],"qs":[{"type":"fill","zh":"我昨天＿＿看电影。","ko":"나 어제 영화 안 봤어.","choices":["没","不","别","也"],"answer":"没","full":{"zh":"我昨天没看电影。","py":"Wǒ zuótiān méi kàn diànyǐng.","ko":"나 어제 영화 안 봤어."},"why":"과거에 안 한 일은 没."},{"type":"fill","zh":"我＿＿喜欢喝咖啡。","ko":"나는 커피를 안 좋아해.","choices":["不","没","没有","别"],"answer":"不","full":{"zh":"我不喜欢喝咖啡。","py":"Wǒ bù xǐhuan hē kāfēi.","ko":"나는 커피를 안 좋아해."},"why":"좋아하지 않는 것(습관·마음)은 不."},{"type":"fill","zh":"明天我＿＿去学校。","ko":"내일 나 학교 안 가.","choices":["不","没","没有","别"],"answer":"不","full":{"zh":"明天我不去学校。","py":"Míngtiān wǒ bú qù xuéxiào.","ko":"내일 나 학교 안 가."},"why":"앞으로 안 할 일은 不."},{"type":"pick","ko":"나 아직 밥 안 먹었어.","choices":["我还没吃饭。","我还不吃饭。","我还没吃饭了。"],"answer":"我还没吃饭。","full":{"zh":"我还没吃饭。","py":"Wǒ hái méi chī fàn.","ko":"나 아직 밥 안 먹었어."},"why":"아직 안 한 일은 没, 그리고 了는 붙이지 않아요."}]},{"id":"g08","lv":1,"title":"会 · 能 · 可以 · 想 · 要 — 동사 앞에 붙는 말","tag":"能愿动词","point":"모두 동사 앞에 와요. 会 = 배워서 할 줄 안다, 能 = (조건·능력이 돼서) 할 수 있다, 可以 = 해도 된다, 想 = ~하고 싶다, 要 = ~하려고 한다.","pattern":["주어 + 会/能/可以/想/要 + 동사"],"ex":[{"zh":"我会说汉语。","py":"Wǒ huì shuō Hànyǔ.","ko":"나 중국어 할 줄 알아."},{"zh":"我可以进来吗？","py":"Wǒ kěyǐ jìnlái ma?","ko":"들어가도 돼요?"},{"zh":"我想喝水。","py":"Wǒ xiǎng hē shuǐ.","ko":"나 물 마시고 싶어."}],"qs":[{"type":"fill","zh":"老师，我＿＿回家吗？","ko":"선생님, 집에 가도 돼요?","choices":["可以","会","想","是"],"answer":"可以","full":{"zh":"老师，我可以回家吗？","py":"Lǎoshī, wǒ kěyǐ huí jiā ma?","ko":"선생님, 집에 가도 돼요?"},"why":"'~해도 된다'(허락)는 可以."},{"type":"fill","zh":"他＿＿说一点儿汉语。","ko":"그는 중국어를 조금 할 줄 알아.","choices":["会","可以","是","在"],"answer":"会","full":{"zh":"他会说一点儿汉语。","py":"Tā huì shuō yìdiǎnr Hànyǔ.","ko":"그는 중국어를 조금 할 줄 알아."},"why":"배워서 할 줄 아는 것은 会."},{"type":"fill","zh":"我＿＿去中国旅游。","ko":"나 중국 여행 가고 싶어.","choices":["想","是","在","有"],"answer":"想","full":{"zh":"我想去中国旅游。","py":"Wǒ xiǎng qù Zhōngguó lǚyóu.","ko":"나 중국 여행 가고 싶어."},"why":"'~하고 싶다'는 想 + 동사."},{"type":"fill","zh":"这儿不＿＿打电话。","ko":"여기서는 전화하면 안 돼.","choices":["能","会","想","有"],"answer":"能","full":{"zh":"这儿不能打电话。","py":"Zhèr bù néng dǎ diànhuà.","ko":"여기서는 전화하면 안 돼."},"why":"'~하면 안 된다'(금지)는 不能 (不可以도 돼요)."}]},{"id":"g09","lv":1,"title":"了 — 했다(완료) · 이제 ~다(변화)","tag":"了1 · 了2","point":"동사 바로 뒤의 了는 동작이 끝났다는 뜻(~했다)이에요. 문장 끝의 了는 상황이 바뀌었다는 뜻(이제 ~다, ~하게 됐다)이에요. 부정은 没(有) + 동사이고, 이때 了는 빼요.","pattern":["동사 + 了 + (수량) + 목적어","문장 + 了","没(有) + 동사 (了 없음)"],"ex":[{"zh":"我昨天买了一件衣服。","py":"Wǒ zuótiān mǎi le yí jiàn yīfu.","ko":"나 어제 옷 한 벌 샀어."},{"zh":"下雨了。","py":"Xià yǔ le.","ko":"비 온다. (안 오다가 이제 와)"},{"zh":"我二十岁了。","py":"Wǒ èrshí suì le.","ko":"나 이제 스무 살이야."}],"qs":[{"type":"fill","zh":"他喝＿＿三杯咖啡。","ko":"그는 커피를 세 잔 마셨어.","choices":["了","的","吗","呢"],"answer":"了","full":{"zh":"他喝了三杯咖啡。","py":"Tā hē le sān bēi kāfēi.","ko":"그는 커피를 세 잔 마셨어."},"why":"다 한 동작은 동사 뒤에 了."},{"type":"pick","ko":"나 어제 학교에 안 갔어.","choices":["我昨天没去学校。","我昨天没去学校了。","我昨天不去学校了。"],"answer":"我昨天没去学校。","full":{"zh":"我昨天没去学校。","py":"Wǒ zuótiān méi qù xuéxiào.","ko":"나 어제 학교에 안 갔어."},"why":"没 문장에는 了를 붙이지 않아요."},{"type":"fill","zh":"天气热＿＿。","ko":"날씨가 더워졌어.","choices":["了","的","吗","很"],"answer":"了","full":{"zh":"天气热了。","py":"Tiānqì rè le.","ko":"날씨가 더워졌어."},"why":"문장 끝 了 = 상황이 바뀌었다."},{"type":"pick","ko":"나 어제 사과 세 개 샀어.","choices":["我昨天买了三个苹果。","我昨天买三个了苹果。","我昨天了买三个苹果。"],"answer":"我昨天买了三个苹果。","full":{"zh":"我昨天买了三个苹果。","py":"Wǒ zuótiān mǎi le sān ge píngguǒ.","ko":"나 어제 사과 세 개 샀어."},"why":"완료의 了는 동사 바로 뒤에 와요."}]},{"id":"g10","lv":1,"title":"在 · 正在 … 呢 — ~하고 있다","tag":"进行态","point":"동사 앞에 在나 正在를 붙이면 '~하고 있다'예요. 문장 끝에 呢를 함께 쓰면 더 자연스러워요. '在 + 장소'(~에서)와 헷갈리지 마세요.","pattern":["주어 + 在/正在 + 동사 + (呢)"],"ex":[{"zh":"妈妈在做饭。","py":"Māma zài zuò fàn.","ko":"엄마는 밥 하고 계셔."},{"zh":"他正在打电话呢。","py":"Tā zhèngzài dǎ diànhuà ne.","ko":"그는 지금 전화하고 있어."},{"zh":"你在看什么？","py":"Nǐ zài kàn shénme?","ko":"너 뭐 보고 있어?"}],"qs":[{"type":"fill","zh":"弟弟＿＿睡觉呢。","ko":"남동생은 자고 있어.","choices":["在","是","有","了"],"answer":"在","full":{"zh":"弟弟在睡觉呢。","py":"Dìdi zài shuìjiào ne.","ko":"남동생은 자고 있어."},"why":"'~하고 있다'는 동사 앞에 在."},{"type":"fill","zh":"我正在吃饭＿＿。","ko":"나 지금 밥 먹고 있어.","choices":["呢","吗","的","也"],"answer":"呢","full":{"zh":"我正在吃饭呢。","py":"Wǒ zhèngzài chī fàn ne.","ko":"나 지금 밥 먹고 있어."},"why":"진행 문장 끝에는 呢를 자주 붙여요."},{"type":"fill","zh":"他们＿＿上课呢。","ko":"그들은 수업하고 있어.","choices":["在","是","有","了"],"answer":"在","full":{"zh":"他们在上课呢。","py":"Tāmen zài shàngkè ne.","ko":"그들은 수업하고 있어."},"why":"'~하고 있다'는 동사 앞에 在, 끝에 呢."},{"type":"pick","ko":"엄마는 지금 TV를 보고 계셔.","choices":["妈妈正在看电视。","妈妈看电视正在。","妈妈正看在电视。"],"answer":"妈妈正在看电视。","full":{"zh":"妈妈正在看电视。","py":"Māma zhèngzài kàn diànshì.","ko":"엄마는 지금 TV를 보고 계셔."},"why":"正在는 동사 앞에 와요."}]},{"id":"g11","lv":1,"title":"两本书 — 숫자 + 양사 + 명사","tag":"数量短语","point":"중국어는 숫자와 명사 사이에 양사가 꼭 들어가요 (一个人, 两本书, 三杯茶). 양사 앞의 2는 二이 아니라 两이에요. 这·那 + 양사 + 명사도 같아요 (这本书).","pattern":["숫자 + 양사 + 명사","这/那 + 양사 + 명사"],"ex":[{"zh":"我有两个妹妹。","py":"Wǒ yǒu liǎng ge mèimei.","ko":"나는 여동생이 두 명 있어."},{"zh":"我要三杯茶。","py":"Wǒ yào sān bēi chá.","ko":"차 세 잔 주세요."},{"zh":"这本书是我的。","py":"Zhè běn shū shì wǒ de.","ko":"이 책은 내 거야."}],"qs":[{"type":"fill","zh":"我买了＿＿本书。","ko":"나 책 두 권 샀어.","choices":["两","二","第二","两个"],"answer":"两","full":{"zh":"我买了两本书。","py":"Wǒ mǎi le liǎng běn shū.","ko":"나 책 두 권 샀어."},"why":"양사 앞의 2는 两. 양사는 하나만 (两个本 ✕)."},{"type":"fill","zh":"我想买一＿＿衣服。","ko":"나 옷 한 벌 사고 싶어.","choices":["件","本","口","杯"],"answer":"件","full":{"zh":"我想买一件衣服。","py":"Wǒ xiǎng mǎi yí jiàn yīfu.","ko":"나 옷 한 벌 사고 싶어."},"why":"옷은 件으로 세요."},{"type":"fill","zh":"我家有四＿＿人。","ko":"우리 집은 네 식구야.","choices":["口","本","件","杯"],"answer":"口","full":{"zh":"我家有四口人。","py":"Wǒ jiā yǒu sì kǒu rén.","ko":"우리 집은 네 식구야."},"why":"식구 수를 셀 때는 口."},{"type":"pick","ko":"나는 고양이가 두 마리 있어.","choices":["我有两只猫。","我有二只猫。","我有两猫。"],"answer":"我有两只猫。","full":{"zh":"我有两只猫。","py":"Wǒ yǒu liǎng zhī māo.","ko":"나는 고양이가 두 마리 있어."},"why":"양사 앞의 2는 两, 동물은 只로 세요. 양사는 빠지면 안 돼요."}]},{"id":"g12","lv":1,"title":"날짜 · 요일 · 시각 · 돈","tag":"时间·钱数表示法","point":"날짜는 큰 단위부터: 年 → 月 → 日/号. 요일은 星期一~星期六, 일요일은 星期天(星期日). 시각은 点(시)·分(분)·半(반). 돈은 말할 때 块(= 元)를 써요.","pattern":["○月○号 星期○","○点○分 / ○点半","○块(钱)"],"ex":[{"zh":"今天十月九号，星期五。","py":"Jīntiān shí yuè jiǔ hào, xīngqīwǔ.","ko":"오늘은 10월 9일 금요일이야."},{"zh":"现在三点半。","py":"Xiànzài sān diǎn bàn.","ko":"지금 3시 반이야."},{"zh":"一杯咖啡二十块。","py":"Yì bēi kāfēi èrshí kuài.","ko":"커피 한 잔에 20위안이야."}],"qs":[{"type":"fill","zh":"现在八点＿＿。","ko":"지금 8시 반이야.","choices":["半","分","号","块"],"answer":"半","full":{"zh":"现在八点半。","py":"Xiànzài bā diǎn bàn.","ko":"지금 8시 반이야."},"why":"'~시 반'은 点 뒤에 半."},{"type":"fill","zh":"今天星期＿＿？","ko":"오늘 무슨 요일이야?","choices":["几","什么","多少","哪"],"answer":"几","full":{"zh":"今天星期几？","py":"Jīntiān xīngqī jǐ?","ko":"오늘 무슨 요일이야?"},"why":"요일은 星期 + 숫자라서 星期几로 물어요."},{"type":"pick","ko":"오늘은 5월 1일이야.","choices":["今天五月一号。","今天一号五月。","今天五号一月。"],"answer":"今天五月一号。","full":{"zh":"今天五月一号。","py":"Jīntiān wǔ yuè yī hào.","ko":"오늘은 5월 1일이야."},"why":"날짜는 큰 단위부터: 月 → 号."},{"type":"fill","zh":"这个面包五＿＿钱。","ko":"이 빵은 5위안이야.","choices":["块","点","号","岁"],"answer":"块","full":{"zh":"这个面包五块钱。","py":"Zhège miànbāo wǔ kuài qián.","ko":"이 빵은 5위안이야."},"why":"말할 때 돈 단위는 块."}]},{"id":"g13","lv":2,"title":"比 — A는 B보다 ~하다","tag":"比字句","point":"'A는 B보다 ~하다'는 A + 比 + B + 형용사예요. 이때 형용사 앞에 很·非常을 쓰지 않아요 (哥哥比我很高 ✕). 얼마나 차이 나는지는 형용사 뒤에 붙여요 (比我大三岁). 'A는 B만큼 ~하지 않다'는 A + 没有 + B + (那么) + 형용사예요.","pattern":["A + 比 + B + 형용사","A + 比 + B + 형용사 + 차이","A + 没有 + B + (那么) + 형용사"],"ex":[{"zh":"哥哥比我高。","py":"Gēge bǐ wǒ gāo.","ko":"형은 나보다 키가 커."},{"zh":"今天比昨天冷一点儿。","py":"Jīntiān bǐ zuótiān lěng yìdiǎnr.","ko":"오늘은 어제보다 조금 추워."},{"zh":"我没有他那么忙。","py":"Wǒ méiyǒu tā nàme máng.","ko":"나는 그 사람만큼 바쁘지 않아."}],"qs":[{"type":"fill","zh":"地铁＿＿公交车快。","ko":"지하철이 버스보다 빨라.","choices":["比","很","和","跟"],"answer":"比","full":{"zh":"地铁比公交车快。","py":"Dìtiě bǐ gōngjiāochē kuài.","ko":"지하철이 버스보다 빨라."},"why":"'A는 B보다 ~하다'는 A + 比 + B + 형용사."},{"type":"pick","ko":"그는 나보다 두 살 많아.","choices":["他比我大两岁。","他比我两岁大。","他比我很大。"],"answer":"他比我大两岁。","full":{"zh":"他比我大两岁。","py":"Tā bǐ wǒ dà liǎng suì.","ko":"그는 나보다 두 살 많아."},"why":"차이(两岁)는 형용사 뒤에 오고, 比 문장에는 很을 쓰지 않아요."},{"type":"pick","ko":"남동생은 나만큼 크지 않아.","choices":["弟弟没有我高。","弟弟不有我高。","弟弟没有高我。"],"answer":"弟弟没有我高。","full":{"zh":"弟弟没有我高。","py":"Dìdi méiyǒu wǒ gāo.","ko":"남동생은 나만큼 크지 않아."},"why":"A + 没有 + B + 형용사 = A는 B만큼 ~하지 않다."},{"type":"fill","zh":"他比我大＿＿岁。","ko":"그는 나보다 세 살 많아.","choices":["三","很","非常","太"],"answer":"三","full":{"zh":"他比我大三岁。","py":"Tā bǐ wǒ dà sān suì.","ko":"그는 나보다 세 살 많아."},"why":"比 문장에는 很·非常·太를 못 쓰고, 차이는 형용사 뒤에 와요."}]},{"id":"g14","lv":2,"title":"过 — ~해 본 적이 있다","tag":"经历态 过","point":"동사 바로 뒤의 过는 '~해 본 적이 있다'(경험)예요. 부정은 没(有) + 동사 + 过예요. 过는 가볍게(경성) 읽어요.","pattern":["동사 + 过 (~해 본 적 있다)","没(有) + 동사 + 过","동사 + 过 + … + 吗？"],"ex":[{"zh":"我去过中国。","py":"Wǒ qù guo Zhōngguó.","ko":"나 중국에 가 본 적 있어."},{"zh":"你吃过饺子吗？","py":"Nǐ chī guo jiǎozi ma?","ko":"너 교자 먹어 봤어?"},{"zh":"我没看过这个电影。","py":"Wǒ méi kàn guo zhège diànyǐng.","ko":"나 이 영화 본 적 없어."}],"qs":[{"type":"fill","zh":"我学＿＿一点儿汉语。","ko":"나 중국어를 조금 배운 적 있어.","choices":["过","着","得","地"],"answer":"过","full":{"zh":"我学过一点儿汉语。","py":"Wǒ xué guo yìdiǎnr Hànyǔ.","ko":"나 중국어를 조금 배운 적 있어."},"why":"경험은 동사 뒤에 过."},{"type":"pick","ko":"나 그 사람 만난 적 없어.","choices":["我没见过他。","我不见过他。","我没见他过。"],"answer":"我没见过他。","full":{"zh":"我没见过他。","py":"Wǒ méi jiàn guo tā.","ko":"나 그 사람 만난 적 없어."},"why":"경험의 부정은 没 + 동사 + 过 (不 ✕)."},{"type":"fill","zh":"你见＿＿他的妈妈吗？","ko":"너 걔 엄마 만나 본 적 있어?","choices":["过","着","得","地"],"answer":"过","full":{"zh":"你见过他的妈妈吗？","py":"Nǐ jiàn guo tā de māma ma?","ko":"너 걔 엄마 만나 본 적 있어?"},"why":"'~해 본 적 있다'는 동사 + 过."},{"type":"pick","ko":"나 이 노래 들어 본 적 있어.","choices":["我听过这个歌。","我过听这个歌。","我听这个歌过。"],"answer":"我听过这个歌。","full":{"zh":"我听过这个歌。","py":"Wǒ tīng guo zhège gē.","ko":"나 이 노래 들어 본 적 있어."},"why":"过는 동사 바로 뒤에 와요."}]},{"id":"g15","lv":2,"title":"着 — ~해 있다 · ~한 채로","tag":"持续态 着","point":"동사 뒤 着는 동작이나 상태가 계속되고 있다는 뜻이에요. '문이 열려 있다', '옷을 입고 있다'처럼 상태를 말할 때 많이 써요. '어디에 무엇이 ~해 있다'는 장소 + 동사 + 着 + 사물이에요 (外面站着一个人).","pattern":["동사 + 着 (~해 있다)","장소 + 동사 + 着 + (수량) + 사물 (~에 …이 ~해 있다)"],"ex":[{"zh":"门开着。","py":"Mén kāi zhe.","ko":"문이 열려 있어."},{"zh":"她穿着红色的衣服。","py":"Tā chuān zhe hóngsè de yīfu.","ko":"그녀는 빨간 옷을 입고 있어."},{"zh":"教室里坐着很多学生。","py":"Jiàoshì li zuò zhe hěn duō xuésheng.","ko":"교실에 학생들이 많이 앉아 있어."}],"qs":[{"type":"fill","zh":"外面下＿＿雨呢。","ko":"밖에 비가 오고 있어.","choices":["着","过","得","的"],"answer":"着","full":{"zh":"外面下着雨呢。","py":"Wàimiàn xià zhe yǔ ne.","ko":"밖에 비가 오고 있어."},"why":"계속되는 상태는 동사 뒤에 着."},{"type":"fill","zh":"教室的门开＿＿。","ko":"교실 문이 열려 있어.","choices":["着","过","得","吧"],"answer":"着","full":{"zh":"教室的门开着。","py":"Jiàoshì de mén kāi zhe.","ko":"교실 문이 열려 있어."},"why":"'~해 있다'(상태)는 동사 + 着."},{"type":"pick","ko":"밖에 사람이 한 명 서 있어.","choices":["外面站着一个人。","外面着站一个人。","一个人站着外面。"],"answer":"外面站着一个人。","full":{"zh":"外面站着一个人。","py":"Wàimian zhàn zhe yí ge rén.","ko":"밖에 사람이 한 명 서 있어."},"why":"장소 + 동사 + 着 + 수량 + 사람·사물 = 어디에 누가(무엇이) ~해 있다. 着는 동사 바로 뒤에 와요."},{"type":"fill","zh":"他穿＿＿一件白色的衣服。","ko":"그는 흰 옷을 입고 있어.","choices":["着","地","得","的"],"answer":"着","full":{"zh":"他穿着一件白色的衣服。","py":"Tā chuān zhe yí jiàn báisè de yīfu.","ko":"그는 흰 옷을 입고 있어."},"why":"입고 있는 상태는 穿着."}]},{"id":"g16","lv":2,"title":"看看 · 休息休息 — 동사 겹쳐 쓰기","tag":"动词重叠","point":"동사를 두 번 쓰면 '좀 ~해 보다, 한번 ~하다'처럼 가볍고 부드러운 말이 돼요. 한 글자 동사는 AA·A一A(看看, 看一看), 두 글자 동사는 ABAB(休息休息)예요. 뒤에 오는 글자는 가볍게 읽어요.","pattern":["AA · A一A : 看看 · 看一看","ABAB : 休息休息"],"ex":[{"zh":"你看看这本书。","py":"Nǐ kànkan zhè běn shū.","ko":"이 책 좀 봐 봐."},{"zh":"我们出去走走吧。","py":"Wǒmen chūqù zǒuzou ba.","ko":"우리 나가서 좀 걷자."},{"zh":"你想一想。","py":"Nǐ xiǎng yi xiǎng.","ko":"한번 생각해 봐."}],"qs":[{"type":"fill","zh":"你听＿＿这个歌。","ko":"이 노래 좀 들어 봐.","choices":["听","的","很","吧"],"answer":"听","full":{"zh":"你听听这个歌。","py":"Nǐ tīngting zhège gē.","ko":"이 노래 좀 들어 봐."},"why":"'좀 ~해 보다'는 동사를 겹쳐요 (听听)."},{"type":"pick","ko":"우리 좀 쉬자.","choices":["我们休息休息吧。","我们休休息息吧。","我们休息一休息吧。"],"answer":"我们休息休息吧。","full":{"zh":"我们休息休息吧。","py":"Wǒmen xiūxi xiūxi ba.","ko":"우리 좀 쉬자."},"why":"두 글자 동사는 ABAB로 겹쳐요 (休息休息)."},{"type":"fill","zh":"你等一＿＿。","ko":"좀 기다려 봐.","choices":["等","次","个","本"],"answer":"等","full":{"zh":"你等一等。","py":"Nǐ děng yi děng.","ko":"좀 기다려 봐."},"why":"한 글자 동사는 A一A로 겹칠 수 있어요 (等一等)."},{"type":"pick","ko":"엄마, 이거 좀 봐 봐요.","choices":["妈妈，你看看这个。","妈妈，你看看看这个。","妈妈，你看一看看这个。"],"answer":"妈妈，你看看这个。","full":{"zh":"妈妈，你看看这个。","py":"Māma, nǐ kànkan zhège.","ko":"엄마, 이거 좀 봐 봐요."},"why":"한 글자 동사는 두 번만 (看看 · 看一看)."}]},{"id":"g17","lv":2,"title":"看完 · 听懂 · 写错 — 결과를 붙이기","tag":"结果补语","point":"동사 뒤에 결과를 붙여 '해서 어떻게 됐는지'를 말해요. 看完(다 봤다), 听懂(듣고 이해했다), 写错(잘못 썼다), 做好(다 했다), 学会(배워서 할 줄 알게 됐다). 부정은 没 + 동사 + 결과예요 (没听懂).","pattern":["동사 + 完 / 懂 / 错 / 好 / 会","没 + 동사 + 결과"],"ex":[{"zh":"我看完了这本书。","py":"Wǒ kàn wán le zhè běn shū.","ko":"나 이 책 다 읽었어."},{"zh":"你听懂了吗？","py":"Nǐ tīng dǒng le ma?","ko":"너 알아들었어?"},{"zh":"对不起，我写错了。","py":"Duìbuqǐ, wǒ xiě cuò le.","ko":"미안, 내가 잘못 썼어."}],"qs":[{"type":"fill","zh":"我没听＿＿，你再说一次。","ko":"못 알아들었어, 다시 한 번 말해 줘.","choices":["懂","着","得","地"],"answer":"懂","full":{"zh":"我没听懂，你再说一次。","py":"Wǒ méi tīng dǒng, nǐ zài shuō yí cì.","ko":"못 알아들었어, 다시 한 번 말해 줘."},"why":"'듣고 이해하다'는 听懂, 부정은 没听懂."},{"type":"fill","zh":"衣服洗＿＿了。","ko":"옷 다 빨았어.","choices":["好","懂","着","得"],"answer":"好","full":{"zh":"衣服洗好了。","py":"Yīfu xǐ hǎo le.","ko":"옷 다 빨았어."},"why":"'다 했다, 잘 마쳤다'는 동사 + 好."},{"type":"fill","zh":"我学＿＿了游泳。","ko":"나 수영 배워서 할 줄 알게 됐어.","choices":["会","懂","错","着"],"answer":"会","full":{"zh":"我学会了游泳。","py":"Wǒ xué huì le yóuyǒng.","ko":"나 수영 배워서 할 줄 알게 됐어."},"why":"배워서 할 줄 알게 된 결과는 学会."},{"type":"pick","ko":"나 이 영화 다 봤어.","choices":["我看完了这个电影。","我完看了这个电影。","我看了完这个电影。"],"answer":"我看完了这个电影。","full":{"zh":"我看完了这个电影。","py":"Wǒ kàn wán le zhège diànyǐng.","ko":"나 이 영화 다 봤어."},"why":"결과(完)는 동사 바로 뒤, 了는 그 뒤에 와요."}]},{"id":"g18","lv":2,"title":"进来 · 出去 · 回来 — 방향을 붙이기","tag":"趋向补语","point":"동사 뒤의 来는 '말하는 사람 쪽으로', 去는 '그 반대쪽으로'예요. 进(들어)·出(나)·上(올라)·下(내려)·回(돌아)·过(건너) 뒤에 来/去를 붙이면 방향이 분명해져요. 进来 = 들어오다, 出去 = 나가다.","pattern":["동사 + 来 (이쪽으로) / 去 (저쪽으로)","进·出·上·下·回·过 + 来/去"],"ex":[{"zh":"请进来！","py":"Qǐng jìnlái!","ko":"들어오세요!"},{"zh":"爸爸回来了。","py":"Bàba huílái le.","ko":"아빠 돌아오셨어."},{"zh":"他出去了。","py":"Tā chūqù le.","ko":"그는 나갔어."}],"qs":[{"type":"fill","zh":"我在楼下，你下＿＿吧。","ko":"나 아래층에 있어, 내려와.","choices":["来","去","上","出"],"answer":"来","full":{"zh":"我在楼下，你下来吧。","py":"Wǒ zài lóu xià, nǐ xiàlái ba.","ko":"나 아래층에 있어, 내려와."},"why":"말하는 사람(아래층) 쪽으로 오니까 下来."},{"type":"fill","zh":"他不在家，他出＿＿了。","ko":"그는 집에 없어, 나갔어.","choices":["去","来","上","进"],"answer":"去","full":{"zh":"他不在家，他出去了。","py":"Tā bú zài jiā, tā chūqù le.","ko":"그는 집에 없어, 나갔어."},"why":"안에서 밖으로, 멀어지는 쪽이니까 出去."},{"type":"fill","zh":"你在外面吗？快进＿＿吧！","ko":"너 밖에 있어? 얼른 들어와!","choices":["来","去","上","下"],"answer":"来","full":{"zh":"你在外面吗？快进来吧！","py":"Nǐ zài wàimiàn ma? Kuài jìnlái ba!","ko":"너 밖에 있어? 얼른 들어와!"},"why":"말하는 사람(안) 쪽으로 들어오니까 进来."},{"type":"pick","ko":"우리 올라가자.","choices":["我们上去吧。","我们去上吧。","我们上来去吧。"],"answer":"我们上去吧。","full":{"zh":"我们上去吧。","py":"Wǒmen shàngqù ba.","ko":"우리 올라가자."},"why":"지금 있는 곳에서 멀어지며 올라가니까 上去."}]},{"id":"g19","lv":2,"title":"说得很好 — 얼마나 잘 하는지 (得)","tag":"状态补语 得","point":"동작을 어떻게, 얼마나 잘 하는지 말할 때 동사 + 得 + 형용사예요. 목적어가 있으면 목적어를 동사 앞으로 보내요 (他汉语说得很好). 他说得汉语很好 ✕","pattern":["동사 + 得 + (很) + 형용사","목적어 + 동사 + 得 + 형용사"],"ex":[{"zh":"她唱得很好听。","py":"Tā chàng de hěn hǎotīng.","ko":"그녀는 노래를 듣기 좋게 불러."},{"zh":"你汉语说得很好！","py":"Nǐ Hànyǔ shuō de hěn hǎo!","ko":"너 중국어 잘한다!"},{"zh":"我昨天睡得很晚。","py":"Wǒ zuótiān shuì de hěn wǎn.","ko":"나 어제 늦게 잤어."}],"qs":[{"type":"fill","zh":"他走＿＿很慢。","ko":"그는 천천히 걸어.","choices":["得","的","地","了"],"answer":"得","full":{"zh":"他走得很慢。","py":"Tā zǒu de hěn màn.","ko":"그는 천천히 걸어."},"why":"동사 뒤에서 '어떻게'를 말할 때는 得."},{"type":"pick","ko":"그는 중국어를 아주 잘해.","choices":["他汉语说得很好。","他说得汉语很好。","他汉语说很好得。"],"answer":"他汉语说得很好。","full":{"zh":"他汉语说得很好。","py":"Tā Hànyǔ shuō de hěn hǎo.","ko":"그는 중국어를 아주 잘해."},"why":"목적어(汉语)는 동사 앞으로 보내고, 동사 바로 뒤에 得 + 형용사를 붙여요."},{"type":"fill","zh":"她汉字写＿＿很漂亮。","ko":"그녀는 한자를 예쁘게 써.","choices":["得","的","地","了"],"answer":"得","full":{"zh":"她汉字写得很漂亮。","py":"Tā Hànzì xiě de hěn piàoliang.","ko":"그녀는 한자를 예쁘게 써."},"why":"동사 뒤에서 '어떻게'를 말할 때는 得."},{"type":"pick","ko":"나 어제 잘 잤어.","choices":["我昨天睡得很好。","我昨天睡很好得。","我昨天很好睡得。"],"answer":"我昨天睡得很好。","full":{"zh":"我昨天睡得很好。","py":"Wǒ zuótiān shuì de hěn hǎo.","ko":"나 어제 잘 잤어."},"why":"동사 + 得 + 형용사 순서예요."}]},{"id":"g20","lv":2,"title":"快要…了 — 곧 ~하려고 한다","tag":"要/快要/就要……了","point":"'곧 ~한다'는 快要…了, 快…了, 要…了예요. 문장 끝에 了를 꼭 붙여요. 明天처럼 때를 나타내는 말이 있으면 快要 대신 就要…了를 써요.","pattern":["快要 + 동사/형용사 + 了","快 + 동사/형용사/시간 + 了","때 + 就要 + 동사 + 了"],"ex":[{"zh":"快要下雨了。","py":"Kuàiyào xià yǔ le.","ko":"곧 비가 올 것 같아."},{"zh":"我们明天就要开学了。","py":"Wǒmen míngtiān jiù yào kāixué le.","ko":"우리 내일이면 개학이야."},{"zh":"我的生日快到了。","py":"Wǒ de shēngrì kuài dào le.","ko":"내 생일이 곧 다가와."}],"qs":[{"type":"fill","zh":"火车快要开＿＿。","ko":"기차가 곧 출발해.","choices":["了","的","吗","着"],"answer":"了","full":{"zh":"火车快要开了。","py":"Huǒchē kuàiyào kāi le.","ko":"기차가 곧 출발해."},"why":"快要…了 — 끝에 了를 붙여요."},{"type":"pick","ko":"곧 열두 시야.","choices":["快十二点了。","十二点快了。","快要十二点。"],"answer":"快十二点了。","full":{"zh":"快十二点了。","py":"Kuài shí'èr diǎn le.","ko":"곧 열두 시야."},"why":"快 + 시간 + 了. 끝의 了를 빼면 안 돼요."},{"type":"fill","zh":"电影快要开始＿＿，我们进去吧。","ko":"영화 곧 시작해, 우리 들어가자.","choices":["了","的","着","过"],"answer":"了","full":{"zh":"电影快要开始了，我们进去吧。","py":"Diànyǐng kuàiyào kāishǐ le, wǒmen jìnqù ba.","ko":"영화 곧 시작해, 우리 들어가자."},"why":"快要…了 — 끝에 了를 꼭 붙여요."},{"type":"pick","ko":"우리 다음 주면 시험이야.","choices":["我们下个星期就要考试了。","我们下个星期快要考试了。","我们下个星期就要考试。"],"answer":"我们下个星期就要考试了。","full":{"zh":"我们下个星期就要考试了。","py":"Wǒmen xià ge xīngqī jiù yào kǎoshì le.","ko":"우리 다음 주면 시험이야."},"why":"때를 말하는 말(下个星期)이 있으면 快要 대신 就要…了."}]},{"id":"g21","lv":2,"title":"还是 — A야, 아니면 B야?","tag":"选择问句","point":"'A야, 아니면 B야?' 하고 둘 중에 고르게 할 때 A + 还是 + B예요. 이 질문에는 吗를 붙이지 않아요.","pattern":["A + 还是 + B？"],"ex":[{"zh":"你要红色的还是白色的？","py":"Nǐ yào hóngsè de háishi báisè de?","ko":"빨간 거 줄까, 흰 거 줄까?"},{"zh":"我们坐地铁还是打车？","py":"Wǒmen zuò dìtiě háishi dǎchē?","ko":"우리 지하철 탈까, 택시 탈까?"},{"zh":"你是老师还是学生？","py":"Nǐ shì lǎoshī háishi xuéshēng?","ko":"당신은 선생님이에요, 학생이에요?"}],"qs":[{"type":"fill","zh":"这是你的＿＿他的？","ko":"이거 네 거야, 걔 거야?","choices":["还是","和","也","吗"],"answer":"还是","full":{"zh":"这是你的还是他的？","py":"Zhè shì nǐ de háishi tā de?","ko":"이거 네 거야, 걔 거야?"},"why":"둘 중 하나를 고르는 질문은 还是."},{"type":"pick","ko":"너 커피 마실래, 차 마실래?","choices":["你喝咖啡还是喝茶？","你喝咖啡还是喝茶吗？","你喝咖啡和喝茶吗？"],"answer":"你喝咖啡还是喝茶？","full":{"zh":"你喝咖啡还是喝茶？","py":"Nǐ hē kāfēi háishi hē chá?","ko":"너 커피 마실래, 차 마실래?"},"why":"还是 질문에는 吗를 붙이지 않아요."},{"type":"fill","zh":"你要这个＿＿那个？","ko":"이거 줄까, 저거 줄까?","choices":["还是","和","也","都"],"answer":"还是","full":{"zh":"你要这个还是那个？","py":"Nǐ yào zhège háishi nàge?","ko":"이거 줄까, 저거 줄까?"},"why":"둘 중 고르는 질문은 还是."},{"type":"pick","ko":"너 걸어갈 거야, 택시 타고 갈 거야?","choices":["你走路去还是打车去？","你走路去还是打车去吗？","你走路去和打车去？"],"answer":"你走路去还是打车去？","full":{"zh":"你走路去还是打车去？","py":"Nǐ zǒulù qù háishi dǎchē qù?","ko":"너 걸어갈 거야, 택시 타고 갈 거야?"},"why":"还是 질문에는 吗를 붙이지 않아요. 和는 질문에서 '아니면'이 아니에요."}]},{"id":"g22","lv":2,"title":"虽然…但是 · 因为…所以 — 이어 주는 말","tag":"转折·因果复句","point":"虽然 A，但是 B = 비록 A지만 B. 因为 A，所以 B = A 때문에 그래서 B. 보통 짝으로 같이 쓰고, 한쪽만 써도 돼요.","pattern":["虽然 + A，但是 + B","因为 + A，所以 + B"],"ex":[{"zh":"虽然很贵，但是很好吃。","py":"Suīrán hěn guì, dànshì hěn hǎochī.","ko":"비싸긴 하지만 맛있어."},{"zh":"因为下雨，所以我没去。","py":"Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.","ko":"비가 와서 나 안 갔어."},{"zh":"因为我生病了，所以没去上班。","py":"Yīnwèi wǒ shēngbìng le, suǒyǐ méi qù shàngbān.","ko":"아파서 출근 안 했어."}],"qs":[{"type":"fill","zh":"虽然他很忙，＿＿每天都运动。","ko":"그는 바쁘지만 매일 운동해.","choices":["但是","所以","因为","还是"],"answer":"但是","full":{"zh":"虽然他很忙，但是每天都运动。","py":"Suīrán tā hěn máng, dànshì měi tiān dōu yùndòng.","ko":"그는 바쁘지만 매일 운동해."},"why":"虽然과 짝은 但是 (비록 ~지만)."},{"type":"fill","zh":"因为太累了，＿＿我很早就睡了。","ko":"너무 피곤해서 일찍 잤어.","choices":["所以","但是","虽然","还是"],"answer":"所以","full":{"zh":"因为太累了，所以我很早就睡了。","py":"Yīnwèi tài lèi le, suǒyǐ wǒ hěn zǎo jiù shuì le.","ko":"너무 피곤해서 일찍 잤어."},"why":"因为와 짝은 所以 (그래서)."},{"type":"fill","zh":"＿＿下雨了，所以我们没出去。","ko":"비가 와서 우리 안 나갔어.","choices":["因为","虽然","但是","还是"],"answer":"因为","full":{"zh":"因为下雨了，所以我们没出去。","py":"Yīnwèi xià yǔ le, suǒyǐ wǒmen méi chūqù.","ko":"비가 와서 우리 안 나갔어."},"why":"所以와 짝은 因为 (~때문에)."},{"type":"pick","ko":"이 옷은 비싸지만 예뻐.","choices":["这件衣服虽然很贵，但是很漂亮。","这件衣服因为很贵，所以很漂亮。","这件衣服虽然很贵，所以很漂亮。"],"answer":"这件衣服虽然很贵，但是很漂亮。","full":{"zh":"这件衣服虽然很贵，但是很漂亮。","py":"Zhè jiàn yīfu suīrán hěn guì, dànshì hěn piàoliang.","ko":"이 옷은 비싸지만 예뻐."},"why":"'~지만'은 虽然…但是. 虽然과 所以는 짝이 아니에요."}]},{"id":"g23","lv":2,"title":"一…就… — ~하자마자","tag":"紧缩复句","point":"'A하자마자 (바로) B한다'는 一 + A + 就 + B예요. 주어는 一 앞에 와요. 뒤 문장에 주어가 따로 있으면 就는 그 주어 뒤에 써요 (老师一来，我们就上课).","pattern":["주어 + 一 + A + 就 + B","A 주어 + 一 + A，B 주어 + 就 + B"],"ex":[{"zh":"我一到家就睡觉了。","py":"Wǒ yí dào jiā jiù shuìjiào le.","ko":"나는 집에 오자마자 잤어."},{"zh":"他一看就懂了。","py":"Tā yí kàn jiù dǒng le.","ko":"그는 보자마자 이해했어."},{"zh":"老师一来，我们就上课。","py":"Lǎoshī yì lái, wǒmen jiù shàngkè.","ko":"선생님이 오시면 바로 수업해."}],"qs":[{"type":"fill","zh":"我一下课＿＿回家。","ko":"나는 수업 끝나자마자 집에 가.","choices":["就","也","还","都"],"answer":"就","full":{"zh":"我一下课就回家。","py":"Wǒ yí xiàkè jiù huí jiā.","ko":"나는 수업 끝나자마자 집에 가."},"why":"一 A 就 B — '~하자마자'."},{"type":"pick","ko":"그는 학교에 도착하자마자 교실로 가.","choices":["他一到学校就去教室。","他到学校一就去教室。","他一到学校也去教室。"],"answer":"他一到学校就去教室。","full":{"zh":"他一到学校就去教室。","py":"Tā yí dào xuéxiào jiù qù jiàoshì.","ko":"그는 학교에 도착하자마자 교실로 가."},"why":"一는 첫 동작 앞, 就는 두 번째 동작 앞이에요."},{"type":"fill","zh":"他一＿＿家就打开电视。","ko":"그는 집에 오자마자 TV를 켜.","choices":["回","就","也","在"],"answer":"回","full":{"zh":"他一回家就打开电视。","py":"Tā yì huí jiā jiù dǎkāi diànshì.","ko":"그는 집에 오자마자 TV를 켜."},"why":"一 + 첫 동작(回家) + 就 + 다음 동작."},{"type":"pick","ko":"그는 듣자마자 웃었어.","choices":["他一听就笑了。","他听一就笑了。","他一听也笑了。"],"answer":"他一听就笑了。","full":{"zh":"他一听就笑了。","py":"Tā yì tīng jiù xiào le.","ko":"그는 듣자마자 웃었어."},"why":"一는 첫 동작 앞, 就는 두 번째 동작 앞이에요."}]},{"id":"g24","lv":2,"title":"让 · 叫 · 请 + 사람 + 동사","tag":"兼语句","point":"'(누구)에게 ~하게 하다, ~하라고 하다'는 让·叫 + 사람 + 동사예요. 请 + 사람 + 동사는 '~에게 ~해 달라고 하다', 그리고 '대접하다'예요 (我请你吃饭 = 내가 밥 살게).","pattern":["주어 + 让/叫 + 사람 + 동사","주어 + 请 + 사람 + 동사"],"ex":[{"zh":"妈妈让我早一点儿回家。","py":"Māma ràng wǒ zǎo yìdiǎnr huí jiā.","ko":"엄마가 나한테 좀 일찍 들어오래."},{"zh":"老师叫我们多说汉语。","py":"Lǎoshī jiào wǒmen duō shuō Hànyǔ.","ko":"선생님이 우리한테 중국어를 많이 말하라고 하셨어."},{"zh":"今天我请你吃饭。","py":"Jīntiān wǒ qǐng nǐ chī fàn.","ko":"오늘은 내가 밥 살게."}],"qs":[{"type":"fill","zh":"医生＿＿我多喝水。","ko":"의사가 나보고 물을 많이 마시래.","choices":["让","给","和","在"],"answer":"让","full":{"zh":"医生让我多喝水。","py":"Yīshēng ràng wǒ duō hē shuǐ.","ko":"의사가 나보고 물을 많이 마시래."},"why":"'(누구)에게 ~하게 하다'는 让 + 사람 + 동사."},{"type":"pick","ko":"내가 너 커피 살게.","choices":["我请你喝咖啡。","我请喝咖啡你。","我你请喝咖啡。"],"answer":"我请你喝咖啡。","full":{"zh":"我请你喝咖啡。","py":"Wǒ qǐng nǐ hē kāfēi.","ko":"내가 너 커피 살게."},"why":"请 + 사람 + 동사 (~에게 대접하다)."},{"type":"fill","zh":"妈妈＿＿我去买面包。","ko":"엄마가 나보고 빵 사 오래.","choices":["叫","给","和","在"],"answer":"叫","full":{"zh":"妈妈叫我去买面包。","py":"Māma jiào wǒ qù mǎi miànbāo.","ko":"엄마가 나보고 빵 사 오래."},"why":"'(누구)에게 ~하라고 하다'는 叫·让 + 사람 + 동사."},{"type":"pick","ko":"선생님이 우리한테 좀 일찍 오라고 하셨어.","choices":["老师让我们早一点儿来。","老师让早一点儿来我们。","老师我们让早一点儿来。"],"answer":"老师让我们早一点儿来。","full":{"zh":"老师让我们早一点儿来。","py":"Lǎoshī ràng wǒmen zǎo yìdiǎnr lái.","ko":"선생님이 우리한테 좀 일찍 오라고 하셨어."},"why":"让 바로 뒤에 사람(我们), 그다음에 할 일이 와요."}]},{"id":"g31","lv":3,"day":1,"g":["G65","G75","G45"],"title":"순서 — 先…再/然后 · 吃了饭就走","tag":"先…再… · 了…就…","point":"'먼저 A하고, 그다음에 B'는 先A，再B 또는 先A，然后B 예요. 再는 보통 아직 안 한 일에 쓰고, 이미 한 일은 然后로 이어요. 'A하고 (바로) B'는 A + 了 + (목적어) + 就 + B 예요 (我吃了饭就走). '~하기 전에/~한 뒤에'는 동작 뒤에 以前·以后를 붙여요 (吃饭以前 ✓, 以前吃饭 ✕).","pattern":["先 + A，再 + B (아직 안 한 일)","先 + A，然后 + B","A + 了 + (목적어) + 就 + B","동작 + 以前 / 以后，…"],"ex":[{"zh":"我们先吃饭，再去看电影。","py":"Wǒmen xiān chī fàn, zài qù kàn diànyǐng.","ko":"우리 먼저 밥 먹고 영화 보러 가자."},{"zh":"他吃了早饭就去上班了。","py":"Tā chī le zǎofàn jiù qù shàngbān le.","ko":"그는 아침 먹고 바로 출근했어."},{"zh":"睡觉以前，别喝咖啡。","py":"Shuìjiào yǐqián, bié hē kāfēi.","ko":"자기 전에는 커피 마시지 마."}],"qs":[{"type":"fill","zh":"你先洗手，＿＿吃饭。","ko":"먼저 손 씻고, 그다음에 밥 먹어.","choices":["再","就","都","也"],"answer":"再","full":{"zh":"你先洗手，再吃饭。","py":"Nǐ xiān xǐ shǒu, zài chī fàn.","ko":"먼저 손 씻고, 그다음에 밥 먹어."},"why":"아직 안 한 일의 순서는 先A，再B 예요."},{"type":"pick","ko":"나 밥 먹고 바로 나갔어.","choices":["我吃了饭就出去了。","我吃了就饭出去了。","我就吃饭了出去了。"],"answer":"我吃了饭就出去了。","full":{"zh":"我吃了饭就出去了。","py":"Wǒ chī le fàn jiù chūqu le.","ko":"나 밥 먹고 바로 나갔어."},"why":"A + 了 + 목적어 + 就 + B. 就는 뒤 동작(出去) 바로 앞에 와요."},{"type":"fill","zh":"下课＿＿，我们一起去吃饭吧。","ko":"수업 끝난 뒤에 우리 같이 밥 먹으러 가자.","choices":["以后","以前","然后","最后"],"answer":"以后","full":{"zh":"下课以后，我们一起去吃饭吧。","py":"Xiàkè yǐhòu, wǒmen yìqǐ qù chī fàn ba.","ko":"수업 끝난 뒤에 우리 같이 밥 먹으러 가자."},"why":"'~한 뒤에'는 동작 뒤에 以后. 以前은 '~하기 전에'예요."},{"type":"pick","ko":"나는 먼저 밥을 먹고, 그러고 나서 커피를 마셨어.","choices":["我先吃了饭，然后喝了咖啡。","我吃了饭先，然后喝了咖啡。","我先吃了饭，喝了咖啡然后。"],"answer":"我先吃了饭，然后喝了咖啡。","full":{"zh":"我先吃了饭，然后喝了咖啡。","py":"Wǒ xiān chī le fàn, ránhòu hē le kāfēi.","ko":"나는 먼저 밥을 먹고, 그러고 나서 커피를 마셨어."},"why":"先은 첫 동작 앞, 然后는 둘째 동작 앞에 와요. 이미 한 일이라 再 대신 然后를 써요."}]},{"id":"g27","lv":3,"day":3,"g":["G51"],"title":"결과보어 2 — 到·住·走·上","tag":"结果补语","point":"동사 뒤에 붙여 결과를 말하는 말(결과보어)을 네 개 더 배워요. 到는 목표에 닿음(找到 찾아냈다, 买到 사는 데 성공했다), 住는 꽉 붙들어 둠(拿住 꽉 잡다, 记住 외워 두다), 走는 가져가 버림(拿走·开走), 上은 딱 붙음·더해짐(穿上 입다, 写上 써 넣다). 부정은 没 + 동사 + 결과예요. ✕ 不找到 → 没找到.","pattern":["동사 + 到 / 住 / 走 / 上","没 + 동사 + 결과"],"ex":[{"zh":"我找到你的手机了。","py":"Wǒ zhǎo dào nǐ de shǒujī le.","ko":"네 휴대폰 찾았어."},{"zh":"小王开走了我的车。","py":"Xiǎo Wáng kāi zǒu le wǒ de chē.","ko":"샤오왕이 내 차 몰고 갔어."},{"zh":"这些汉字你要记住。","py":"Zhèxiē Hànzì nǐ yào jì zhù.","ko":"이 한자들 꼭 외워 둬."}],"qs":[{"type":"fill","zh":"我买＿＿明天的机票了。","ko":"나 내일 비행기표 구했어.","choices":["到","住","给","在"],"answer":"到","full":{"zh":"我买到明天的机票了。","py":"Wǒ mǎi dào míngtiān de jīpiào le.","ko":"나 내일 비행기표 구했어."},"why":"사려던 걸 손에 넣었으면 买到."},{"type":"pick","ko":"누가 내 컵 가져갔어?","choices":["谁拿走了我的杯子？","谁拿了走我的杯子？","谁走拿了我的杯子？"],"answer":"谁拿走了我的杯子？","full":{"zh":"谁拿走了我的杯子？","py":"Shéi ná zǒu le wǒ de bēizi?","ko":"누가 내 컵 가져갔어?"},"why":"결과(走)는 동사 바로 뒤, 了는 그 뒤."},{"type":"fill","zh":"天冷了，你穿＿＿这件衣服吧。","ko":"날 추워졌어, 이 옷 입어.","choices":["上","到","住","得"],"answer":"上","full":{"zh":"天冷了，你穿上这件衣服吧。","py":"Tiān lěng le, nǐ chuān shàng zhè jiàn yīfu ba.","ko":"날 추워졌어, 이 옷 입어."},"why":"옷을 몸에 걸치는 건 穿上."},{"type":"pick","ko":"나 결국 그 책 못 찾았어.","choices":["我最后没找到那本书。","我最后不找到那本书。","我最后没找那本书到。"],"answer":"我最后没找到那本书。","full":{"zh":"我最后没找到那本书。","py":"Wǒ zuìhòu méi zhǎo dào nà běn shū.","ko":"나 결국 그 책 못 찾았어."},"why":"결과가 안 나왔으면 没 + 동사 + 到. 到는 동사에 딱 붙어요."}]},{"id":"g38","lv":3,"day":3,"g":["G73"],"title":"조건 — 只要…就 · 只有…才","tag":"条件复句","point":"只要 A，就 B = A하기만 하면 B해요 (A면 충분해요). 只有 A，才 B = A해야만 B해요 (A 말고는 안 돼요). 짝이 정해져 있어서 只要는 就와, 只有는 才와 같이 써요 (只要…才 ✕, 只有…就 ✕). 就·才는 뒤 문장의 주어 뒤, 동사 앞에 와요.","pattern":["只要 + A，(주어) + 就 + B","只有 + A，(주어) + 才 + B"],"ex":[{"zh":"只要你想学，我就教你。","py":"Zhǐyào nǐ xiǎng xué, wǒ jiù jiāo nǐ.","ko":"네가 배우고 싶기만 하면 내가 가르쳐 줄게."},{"zh":"只有每天学习，汉语才能学好。","py":"Zhǐyǒu měi tiān xuéxí, Hànyǔ cái néng xuéhǎo.","ko":"매일 공부해야만 중국어를 잘할 수 있어."},{"zh":"只有你去，他才会去。","py":"Zhǐyǒu nǐ qù, tā cái huì qù.","ko":"네가 가야만 걔도 갈 거야."}],"qs":[{"type":"fill","zh":"＿＿你来，我就很高兴。","ko":"네가 와 주기만 하면 나는 기뻐.","choices":["只要","只有","虽然","但是"],"answer":"只要","full":{"zh":"只要你来，我就很高兴。","py":"Zhǐyào nǐ lái, wǒ jiù hěn gāoxìng.","ko":"네가 와 주기만 하면 나는 기뻐."},"why":"뒤에 就가 있으니 짝은 只要 (~하기만 하면)."},{"type":"fill","zh":"只有吃药，病＿＿会好。","ko":"약을 먹어야만 병이 나아.","choices":["才","就","也","都"],"answer":"才","full":{"zh":"只有吃药，病才会好。","py":"Zhǐyǒu chī yào, bìng cái huì hǎo.","ko":"약을 먹어야만 병이 나아."},"why":"只有의 짝은 才 (~해야만 비로소)."},{"type":"fill","zh":"＿＿多问老师，你就能懂。","ko":"선생님께 많이 물어보기만 하면 이해할 수 있어.","choices":["只要","只有","虽然","但是"],"answer":"只要","full":{"zh":"只要多问老师，你就能懂。","py":"Zhǐyào duō wèn lǎoshī, nǐ jiù néng dǒng.","ko":"선생님께 많이 물어보기만 하면 이해할 수 있어."},"why":"뒤 문장에 就가 있으니 只要예요. 只有라면 뒤에 才가 와야 해요."},{"type":"pick","ko":"일요일에만 나는 시간이 있어.","choices":["只有星期天我才有时间。","只要星期天我才有时间。","只有星期天我就有时间。"],"answer":"只有星期天我才有时间。","full":{"zh":"只有星期天我才有时间。","py":"Zhǐyǒu xīngqītiān wǒ cái yǒu shíjiān.","ko":"일요일에만 나는 시간이 있어."},"why":"'그때만'이라는 유일한 조건은 只有…才. 只要는 才와, 只有는 就와 짝이 아니에요."}]},{"id":"g39","lv":3,"day":3,"g":["G70","G71"],"title":"不但…而且 · 虽然…可是","tag":"递进·转折复句","point":"不但 A，而且 B = A일 뿐 아니라 B도 해요. 앞뒤 주어가 같으면 주어는 不但 앞에 한 번만 써요 (不但他会说汉语，而且… ✕ → 他不但会说汉语 ✓). 虽然 A，可是 B = A지만 B예요. 可是는 但是와 같은 뜻이에요. 可是만 써도 되지만, 虽然만 쓰고 뒤의 可是·但是를 빼면 보통 어색해요.","pattern":["주어 + 不但 + A，而且 + B","虽然 + A，可是 + B"],"ex":[{"zh":"他不但会说汉语，而且说得很好。","py":"Tā búdàn huì shuō Hànyǔ, érqiě shuō de hěn hǎo.","ko":"그는 중국어를 할 줄 알 뿐 아니라 잘하기까지 해."},{"zh":"这个菜不但便宜，而且很好吃。","py":"Zhège cài búdàn piányi, érqiě hěn hǎochī.","ko":"이 요리는 쌀 뿐 아니라 맛있기도 해."},{"zh":"虽然外面很冷，可是我想出去走走。","py":"Suīrán wàimiàn hěn lěng, kěshì wǒ xiǎng chūqù zǒuzou.","ko":"밖은 춥지만 나가서 좀 걷고 싶어."}],"qs":[{"type":"fill","zh":"她不但会唱歌，＿＿会跳舞。","ko":"그녀는 노래뿐 아니라 춤도 출 줄 알아.","choices":["而且","可是","所以","因为"],"answer":"而且","full":{"zh":"她不但会唱歌，而且会跳舞。","py":"Tā búdàn huì chàng gē, érqiě huì tiàowǔ.","ko":"그녀는 노래뿐 아니라 춤도 출 줄 알아."},"why":"不但의 짝은 而且 (게다가 ~도)."},{"type":"fill","zh":"虽然很累，＿＿我很高兴。","ko":"피곤하지만 즐거워.","choices":["可是","而且","所以","因为"],"answer":"可是","full":{"zh":"虽然很累，可是我很高兴。","py":"Suīrán hěn lèi, kěshì wǒ hěn gāoxìng.","ko":"피곤하지만 즐거워."},"why":"虽然의 짝은 可是 (= 但是, ~지만)."},{"type":"pick","ko":"나는 커피를 마실 뿐 아니라 차도 마셔.","choices":["我不但喝咖啡，而且也喝茶。","不但我喝咖啡，而且也喝茶。","我不但喝咖啡，可是也喝茶。"],"answer":"我不但喝咖啡，而且也喝茶。","full":{"zh":"我不但喝咖啡，而且也喝茶。","py":"Wǒ búdàn hē kāfēi, érqiě yě hē chá.","ko":"나는 커피를 마실 뿐 아니라 차도 마셔."},"why":"주어가 하나면 주어(我)는 不但 앞에 와요. 不但과 可是는 짝이 아니에요."},{"type":"pick","ko":"이 책은 비싸지만 재미있어.","choices":["这本书虽然很贵，可是很有意思。","这本书虽然很贵，而且很有意思。","这本书可是很贵，虽然很有意思。"],"answer":"这本书虽然很贵，可是很有意思。","full":{"zh":"这本书虽然很贵，可是很有意思。","py":"Zhè běn shū suīrán hěn guì, kěshì hěn yǒu yìsi.","ko":"이 책은 비싸지만 재미있어."},"why":"虽然은 앞, 可是는 뒤에 와요. '~지만'은 而且가 아니라 可是예요."}]},{"id":"g28","lv":3,"day":4,"g":["G53"],"title":"가능보어 — 看得懂·听不懂","tag":"可能补语","point":"동사와 결과 사이에 得를 넣으면 '~할 수 있다', 不를 넣으면 '~할 수 없다'예요(가능보어). 看得懂 읽고 이해할 수 있다, 听不懂 들어도 못 알아듣다, 吃不了 (많아서) 못 먹다, 买不到 (없어서) 못 사다. 能도 '할 수 있다'지만, '해 봐도 결과가 안 나온다'는 보통 가능보어로 말해요. ✕ 我不能听懂 → 我听不懂.","pattern":["동사 + 得 + 결과/방향 (할 수 있다)","동사 + 不 + 결과/방향 (할 수 없다)"],"ex":[{"zh":"这本书你看得懂吗？","py":"Zhè běn shū nǐ kàn de dǒng ma?","ko":"이 책 너 읽고 이해할 수 있어?"},{"zh":"太多了，我吃不完。","py":"Tài duō le, wǒ chī bu wán.","ko":"너무 많아, 나 다 못 먹어."},{"zh":"我听不懂，你说慢一点儿。","py":"Wǒ tīng bu dǒng, nǐ shuō màn yìdiǎnr.","ko":"못 알아듣겠어, 좀 천천히 말해 줘."}],"qs":[{"type":"fill","zh":"他说得太快了，我听＿＿懂。","ko":"걔 말이 너무 빨라서 못 알아듣겠어.","choices":["不","没","得","很"],"answer":"不","full":{"zh":"他说得太快了，我听不懂。","py":"Tā shuō de tài kuài le, wǒ tīng bu dǒng.","ko":"걔 말이 너무 빨라서 못 알아듣겠어."},"why":"'들어도 이해할 수 없다'는 동사와 결과 사이에 不: 听不懂."},{"type":"pick","ko":"중국어 영화, 너 알아들을 수 있어?","choices":["中文电影你听得懂吗？","中文电影你听得懂听不懂吗？","中文电影你听得不懂吗？"],"answer":"中文电影你听得懂吗？","full":{"zh":"中文电影你听得懂吗？","py":"Zhōngwén diànyǐng nǐ tīng de dǒng ma?","ko":"중국어 영화, 너 알아들을 수 있어?"},"why":"得는 동사와 결과 사이: 听得懂. 得와 不를 같이 쓰지 않고, 吗 질문에 听不懂을 또 붙이지 않아요."},{"type":"pick","ko":"나 혼자서는 못 들겠어.","choices":["我一个人拿不动。","我一个人不能拿动。","我一个人拿得不动。"],"answer":"我一个人拿不动。","full":{"zh":"我一个人拿不动。","py":"Wǒ yí ge rén ná bu dòng.","ko":"나 혼자서는 못 들겠어."},"why":"힘이 모자라 못 움직이는 건 동사 + 不动. 不能拿动이라고 하지 않아요."},{"type":"fill","zh":"今天的票已经买＿＿了。","ko":"오늘 표는 이제 살 수가 없어.","choices":["不到","没到","到不","到没"],"answer":"不到","full":{"zh":"今天的票已经买不到了。","py":"Jīntiān de piào yǐjīng mǎi bu dào le.","ko":"오늘 표는 이제 살 수가 없어."},"why":"사려 해도 못 사는 건 买不到. 不는 동사와 到 사이에 와요."}]},{"id":"g36","lv":3,"day":7,"g":["G55"],"title":"~한 지 얼마 됐다 — 了 + 기간 + 了","tag":"时量 + 了","point":"'~한 지 (기간)이 됐다'는 동사 + 了 + 기간 + 了 예요 (他走了三天了). 끝의 了가 '지금까지'를 나타내서, 学·住처럼 계속하는 일이면 보통 지금도 하고 있다는 뜻이에요. 我学了一年汉语는 보통 지난 일로 들리고, 끝에 了를 붙이면(我学了一年汉语了) 지금까지 1년이라는 게 분명해져요. 走·认识·来처럼 한 번 일어나는 일은 '그 일이 있은 지 얼마'라는 뜻이고, 동사 뒤 了를 자주 빼요 (我们认识五年了).","pattern":["동사 + 了 + 기간 + 了 (~한 지 기간이 됐다)","동사 + 了 + 기간 + 목적어 + 了","동사 + 了 + 기간 (보통 지난 일: 그 기간 동안 했다)"],"ex":[{"zh":"小王来了两个星期了。","py":"Xiǎo Wáng lái le liǎng ge xīngqī le.","ko":"샤오왕이 온 지 두 주 됐어."},{"zh":"她在中国住了半年了。","py":"Tā zài Zhōngguó zhù le bàn nián le.","ko":"그녀는 중국에서 산 지 반년 됐어."},{"zh":"我们认识五年了。","py":"Wǒmen rènshi wǔ nián le.","ko":"우리 안 지 오 년 됐어."}],"qs":[{"type":"fill","zh":"她睡了三个小时＿＿。","ko":"그녀는 세 시간째 자고 있어.","choices":["了","过","着","的"],"answer":"了","full":{"zh":"她睡了三个小时了。","py":"Tā shuì le sān ge xiǎoshí le.","ko":"그녀는 세 시간째 자고 있어."},"why":"끝에 了가 붙어야 '지금까지 ~째'가 돼요."},{"type":"pick","ko":"나 중국에 온 지 삼 년 됐어.","choices":["我来中国三年了。","我三年来了中国。","我来中国三年过了。"],"answer":"我来中国三年了。","full":{"zh":"我来中国三年了。","py":"Wǒ lái Zhōngguó sān nián le.","ko":"나 중국에 온 지 삼 년 됐어."},"why":"기간은 동사(+목적어) 뒤에, 끝에 了. 来처럼 한 번 일어나는 일은 동사 뒤 了를 빼도 돼요."},{"type":"pick","ko":"나 중국어 배운 지 이 년 됐어. (지금도 배우는 중)","choices":["我学了两年汉语了。","我学了两年了汉语。","我两年学了汉语了。"],"answer":"我学了两年汉语了。","full":{"zh":"我学了两年汉语了。","py":"Wǒ xué le liǎng nián Hànyǔ le.","ko":"나 중국어 배운 지 이 년 됐어. (지금도 배우는 중)"},"why":"동사 + 了 + 기간 + 목적어 + 了 순서예요. 기간 뒤 了를 목적어 앞에 두면 안 돼요."},{"type":"fill","zh":"他已经走了＿＿了。","ko":"그가 떠난 지 벌써 한 시간 됐어.","choices":["一个小时","一点","一个时","一时"],"answer":"一个小时","full":{"zh":"他已经走了一个小时了。","py":"Tā yǐjīng zǒu le yí ge xiǎoshí le.","ko":"그가 떠난 지 벌써 한 시간 됐어."},"why":"시간의 길이는 一个小时. 一点은 '한 시'(시각)라서 기간이 아니에요."}]},{"id":"g43","lv":3,"day":9,"g":["G07","G43","G08"],"title":"아무도·하나도 — 谁都 · 什么都 · 一个也没有","tag":"任指·一也不","point":"의문사 뒤에 都를 붙이면 '누구나·뭐든'이 되고 (谁都可以来), 都/也 뒤가 부정이면 '아무도·아무것도 ~않다'가 돼요 (我什么都没吃). 都/也는 꼭 不/没 앞에 와요 (我什么不都吃 ✕). '하나도 ~않다'는 一 + 양사 + 명사 + 也/都 + 不/没, '조금도 ~않다'는 一点儿也不예요. 질문이 아닌 문장의 什么는 '뭔가'라는 뜻이 되기도 해요 (我想吃点儿什么 뭐 좀 먹고 싶어).","pattern":["의문사 + 都 + 긍정 → 누구나·뭐든","의문사 + 都/也 + 不/没 + 동사 → 아무 ~도 안 하다","一 + 양사 + 명사 + 也/都 + 不/没 + 동사","一点儿 + 也/都 + 不 + 형용사"],"ex":[{"zh":"我今天什么都没吃。","py":"Wǒ jīntiān shénme dōu méi chī.","ko":"나 오늘 아무것도 안 먹었어."},{"zh":"你们谁都可以来。","py":"Nǐmen shéi dōu kěyǐ lái.","ko":"너희 중 누구든 와도 돼."},{"zh":"教室里一个人也没有。","py":"Jiàoshì li yí ge rén yě méiyǒu.","ko":"교실에 한 명도 없어."}],"qs":[{"type":"fill","zh":"我今天＿＿都不想做。","ko":"나 오늘 아무것도 하기 싫어.","choices":["什么","谁","哪儿","怎么"],"answer":"什么","full":{"zh":"我今天什么都不想做。","py":"Wǒ jīntiān shénme dōu bù xiǎng zuò.","ko":"나 오늘 아무것도 하기 싫어."},"why":"'아무것도'는 什么 + 都 + 부정."},{"type":"pick","ko":"이 일은 아무도 몰라.","choices":["这件事谁都不知道。","这件事谁不都知道。","这件事都谁不知道。"],"answer":"这件事谁都不知道。","full":{"zh":"这件事谁都不知道。","py":"Zhè jiàn shì shéi dōu bù zhīdào.","ko":"이 일은 아무도 몰라."},"why":"순서는 의문사 + 都 + 不. 都가 不 뒤나 의문사 앞에 오면 안 돼요."},{"type":"fill","zh":"这件衣服一点儿＿＿不贵。","ko":"이 옷 하나도 안 비싸.","choices":["也","很","太","还"],"answer":"也","full":{"zh":"这件衣服一点儿也不贵。","py":"Zhè jiàn yīfu yìdiǎnr yě bú guì.","ko":"이 옷 하나도 안 비싸."},"why":"'조금도 ~않다'는 一点儿 + 也(都) + 不."},{"type":"pick","ko":"나 책 한 권도 안 샀어.","choices":["我一本书也没买。","我一书也没买。","我一本书也买。"],"answer":"我一本书也没买。","full":{"zh":"我一本书也没买。","py":"Wǒ yì běn shū yě méi mǎi.","ko":"나 책 한 권도 안 샀어."},"why":"一 + 양사(本) + 명사 + 也 + 没. 양사도, 부정도 빠지면 안 돼요."}]},{"id":"g42","lv":3,"day":11,"g":["G68","G69","G19"],"title":"又…又 · 一边…一边","tag":"又…又·一边…一边","point":"又 A 又 B = A하고 또 B해요. 보통 형용사 두 개로 성질이나 상태를 말해요 (又便宜又好吃). 一边 A 一边 B = A하면서 B해요. 두 동작을 동시에 해요 (一边吃饭一边看电视). 又를 하나만 쓰면 '또'인데, 보통 이미 일어난 일에 써요 (他又来了). 앞으로 또 할 일에는 보통 再를 써요 (明天再来吧). (明天又是星期一了처럼 정해져 돌아오는 일에는 又도 써요)","pattern":["又 + 형용사 + 又 + 형용사","一边 + 동작 + 一边 + 동작","又 + 동사 + 了 (이미 또) / 再 + 동사 (앞으로 또)"],"ex":[{"zh":"这家饭馆的菜又便宜又好吃。","py":"Zhè jiā fànguǎn de cài yòu piányi yòu hǎochī.","ko":"이 식당 음식은 싸고 맛있어."},{"zh":"他喜欢一边听歌一边跑步。","py":"Tā xǐhuan yìbiān tīng gē yìbiān pǎobù.","ko":"그는 노래 들으면서 달리는 걸 좋아해."},{"zh":"你怎么又忘了拿手机？","py":"Nǐ zěnme yòu wàng le ná shǒujī?","ko":"너 왜 또 휴대폰 안 챙겼어?"}],"qs":[{"type":"fill","zh":"她的房间又大＿＿漂亮。","ko":"그녀 방은 크고 예뻐.","choices":["又","也","还","很"],"answer":"又","full":{"zh":"她的房间又大又漂亮。","py":"Tā de fángjiān yòu dà yòu piàoliang.","ko":"그녀 방은 크고 예뻐."},"why":"又 A 又 B — 앞에 又가 있으면 뒤에도 又."},{"type":"fill","zh":"我们一边吃饭＿＿说话。","ko":"우리는 밥 먹으면서 이야기해.","choices":["一边","又","也","还"],"answer":"一边","full":{"zh":"我们一边吃饭一边说话。","py":"Wǒmen yìbiān chī fàn yìbiān shuōhuà.","ko":"우리는 밥 먹으면서 이야기해."},"why":"두 동작을 동시에 하면 一边 A 一边 B."},{"type":"pick","ko":"그 사람 오늘 또 왔어.","choices":["他今天又来了。","他今天再来了。","他今天来又了。"],"answer":"他今天又来了。","full":{"zh":"他今天又来了。","py":"Tā jīntiān yòu lái le.","ko":"그 사람 오늘 또 왔어."},"why":"이미 또 일어난 일은 又. 再는 앞으로 또 할 일에 써요. 又는 동사 앞이에요."},{"type":"pick","ko":"이 사과는 작고 비싸.","choices":["这个苹果又小又贵。","这个苹果一边小一边贵。","这个苹果又小也贵。"],"answer":"这个苹果又小又贵。","full":{"zh":"这个苹果又小又贵。","py":"Zhège píngguǒ yòu xiǎo yòu guì.","ko":"이 사과는 작고 비싸."},"why":"형용사 두 개는 又…又. 一边…一边은 동작에만 써요."}]},{"id":"g33","lv":3,"day":12,"g":["G04","G23","G47"],"title":"~해야 해 / ~할 필요 없어","tag":"应该 · 得 · 必须 · 不用","point":"'~해야 해'는 应该(그러는 게 맞아), 得 děi(말할 때 자주, ~해야겠어), 必须(꼭, 반드시)예요. '~할 필요 없어'는 不用이나 不必를 써요 (不必须 ✕. 不得는 '~하면 안 된다'라는 다른 뜻이에요). 该 + 동사 + 了는 '이제 ~할 때가 됐다'이고 (该睡觉了), 该你了는 '네 차례야'예요.","pattern":["应该 / 得 / 必须 + 동사","不用 / 不必 + 동사 (~할 필요 없어)","该 + 동사 + 了 (~할 때가 됐다)","该 + 사람 + 了 (~의 차례다)"],"ex":[{"zh":"你病了，应该多休息。","py":"Nǐ bìng le, yīnggāi duō xiūxi.","ko":"너 아프니까 푹 쉬어야 해."},{"zh":"太晚了，我得走了。","py":"Tài wǎn le, wǒ děi zǒu le.","ko":"너무 늦었다, 나 가 봐야겠어."},{"zh":"明天不用上班，你多睡一会儿吧。","py":"Míngtiān búyòng shàngbān, nǐ duō shuì yíhuìr ba.","ko":"내일 출근 안 해도 되니까 좀 더 자."}],"qs":[{"type":"fill","zh":"十一点了，＿＿睡觉了。","ko":"열한 시네, 이제 잘 시간이야.","choices":["该","不用","才","再"],"answer":"该","full":{"zh":"十一点了，该睡觉了。","py":"Shíyī diǎn le, gāi shuìjiào le.","ko":"열한 시네, 이제 잘 시간이야."},"why":"该 + 동사 + 了 = 이제 ~할 때가 됐다."},{"type":"pick","ko":"너 내일 안 와도 돼.","choices":["你明天不用来。","你明天来不用。","你明天不必须来。"],"answer":"你明天不用来。","full":{"zh":"你明天不用来。","py":"Nǐ míngtiān búyòng lái.","ko":"너 내일 안 와도 돼."},"why":"'~할 필요 없어'는 不用(또는 不必)이고 동사 앞에 와요."},{"type":"fill","zh":"明天考试，你＿＿早一点儿睡。","ko":"내일 시험이니까 너 반드시 일찍 자야 해.","choices":["必须","不用","不必","才"],"answer":"必须","full":{"zh":"明天考试，你必须早一点儿睡。","py":"Míngtiān kǎoshì, nǐ bìxū zǎo yìdiǎnr shuì.","ko":"내일 시험이니까 너 반드시 일찍 자야 해."},"why":"'반드시 ~해야 해'는 必须. 不用·不必는 '~할 필요 없어'예요."},{"type":"pick","ko":"나 다 불렀어, 이제 네 차례야.","choices":["我唱完了，该你了。","我唱完了，你该了。","我唱完了，得你了。"],"answer":"我唱完了，该你了。","full":{"zh":"我唱完了，该你了。","py":"Wǒ chàng wán le, gāi nǐ le.","ko":"나 다 불렀어, 이제 네 차례야."},"why":"'~의 차례야'는 该 + 사람 + 了. 사람은 该 뒤에 와요."}]},{"id":"g44","lv":3,"day":12,"g":["G57","G63","G46"],"title":"되묻기와 강조 — 不是…吗 · 是…的 · 忙什么","tag":"反问·是…的","point":"不是A吗？는 'A잖아?' 하고 상대도 아는 일을 다시 짚는 말이에요 (你不是说明天来吗？ 내일 온다고 했잖아). 是와 的 사이에 会·能·对 같은 말을 넣으면 '분명 ~해'처럼 말하는 사람의 확신이 강해져요 (他是会来的). 1·2급에서 배운 是…的(언제·어디서 했는지 강조)와는 쓰임이 달라요. 동사 + 什么(啊)는 '~하긴 뭘 ~해' 하고 가볍게 말리는 말이에요 (忙什么啊).","pattern":["不是 + A + 吗？ → A잖아?","是 + 会/能/对… + 的 → 분명 ~해","동사 + 什么(啊)？ → ~하긴 뭘 ~해"],"ex":[{"zh":"你不是说明天来吗？","py":"Nǐ bú shì shuō míngtiān lái ma?","ko":"너 내일 온다고 했잖아?"},{"zh":"没关系，他是会来的。","py":"Méi guānxi, tā shì huì lái de.","ko":"괜찮아, 걔는 꼭 올 거야."},{"zh":"走什么啊？时间还早呢。","py":"Zǒu shénme a? Shíjiān hái zǎo ne.","ko":"가긴 뭘 가? 아직 시간 많아."}],"qs":[{"type":"fill","zh":"你＿＿去过中国吗？","ko":"너 중국 가 봤잖아?","choices":["不是","不","别","不要"],"answer":"不是","full":{"zh":"你不是去过中国吗？","py":"Nǐ bú shì qù guo Zhōngguó ma?","ko":"너 중국 가 봤잖아?"},"why":"'~잖아?' 하고 다시 짚을 때는 不是…吗？ 不·别·不要는 去过 앞에 못 와요."},{"type":"pick","ko":"걔한테 물어봐, 걔는 분명 너를 도와줄 거야.","choices":["你问问他，他是会帮你的。","你问问他，他是帮你会的。","你问问他，他会帮你是的。"],"answer":"你问问他，他是会帮你的。","full":{"zh":"你问问他，他是会帮你的。","py":"Nǐ wènwen tā, tā shì huì bāng nǐ de.","ko":"걔한테 물어봐, 걔는 분명 너를 도와줄 거야."},"why":"是 + 会 + 동사 + 的 순서로 확신을 강조해요."},{"type":"fill","zh":"你忙＿＿啊？先喝杯茶吧。","ko":"바쁘긴 뭐가 바빠? 차부터 한잔 해.","choices":["什么","怎么","为什么","哪儿"],"answer":"什么","full":{"zh":"你忙什么啊？先喝杯茶吧。","py":"Nǐ máng shénme a? Xiān hē bēi chá ba.","ko":"바쁘긴 뭐가 바빠? 차부터 한잔 해."},"why":"동사 뒤에 什么(啊)를 붙이면 '~하긴 뭘 ~해' 하고 말리는 말. 为什么·怎么는 동사 앞에 와요."},{"type":"pick","ko":"너 어제 그 영화 봤잖아?","choices":["你昨天不是看了那个电影吗？","你昨天没是看了那个电影吗？","你昨天不看了那个电影是吗？"],"answer":"你昨天不是看了那个电影吗？","full":{"zh":"你昨天不是看了那个电影吗？","py":"Nǐ zuótiān bú shì kàn le nàge diànyǐng ma?","ko":"너 어제 그 영화 봤잖아?"},"why":"不是 + 하고 싶은 말 + 吗？ 没是는 없는 말이에요."}]},{"id":"g45","lv":3,"day":12,"g":["G38","G36","G42"],"title":"보기에·~에게는 — 看起来 · 看来 · 对…来说","tag":"看起来·对…来说","point":"看起来·看上去는 '겉으로 보기에 ~해 보여'예요. 주어 뒤, 형용사 앞에 와요 (你看起来很累). 看来는 '보아하니 ~인가 봐'로, 본 것을 바탕으로 판단할 때 보통 문장 맨 앞에 써요 (看来他不来了). 내 생각을 말할 때는 在我看来 '내가 보기엔'이라고 해요. 对A来说는 'A에게는·A 입장에서는'이에요. 그리고 하나 더: 不一会儿은 '얼마 안 돼서'라는 뜻이에요 (不一会儿他就来了).","pattern":["주어 + 看起来/看上去 + 형용사","看来 + 판단","在 + 사람 + 看来，…","对 + 사람 + 来说，…","不一会儿，(주어) + 就 + 동사 → 얼마 안 돼서 ~"],"ex":[{"zh":"你看起来有点儿累。","py":"Nǐ kàn qǐlai yǒudiǎnr lèi.","ko":"너 좀 피곤해 보여."},{"zh":"已经八点了，看来他不来了。","py":"Yǐjīng bā diǎn le, kànlái tā bù lái le.","ko":"벌써 여덟 시네, 보아하니 걔 안 오나 봐."},{"zh":"对我来说，学汉语很有意思。","py":"Duì wǒ lái shuō, xué Hànyǔ hěn yǒu yìsi.","ko":"나한테는 중국어 공부가 정말 재미있어."}],"qs":[{"type":"fill","zh":"这个苹果＿＿很好吃。","ko":"이 사과 맛있어 보여.","choices":["看起来","看见","看完","看过"],"answer":"看起来","full":{"zh":"这个苹果看起来很好吃。","py":"Zhège píngguǒ kàn qǐlai hěn hǎochī.","ko":"이 사과 맛있어 보여."},"why":"겉보기로 '~해 보여'는 看起来 + 형용사."},{"type":"pick","ko":"나한테는 이게 제일 맛있어.","choices":["对我来说，这个最好吃。","我对来说，这个最好吃。","对我来，这个最好吃。"],"answer":"对我来说，这个最好吃。","full":{"zh":"对我来说，这个最好吃。","py":"Duì wǒ lái shuō, zhège zuì hǎochī.","ko":"나한테는 이게 제일 맛있어."},"why":"对 + 사람 + 来说 한 덩어리. 사람은 对와 来说 사이에 와요."},{"type":"fill","zh":"在我＿＿，这个电影不错。","ko":"내가 보기엔 이 영화 괜찮아.","choices":["看来","看起来","看见","看看"],"answer":"看来","full":{"zh":"在我看来，这个电影不错。","py":"Zài wǒ kànlái, zhège diànyǐng búcuò.","ko":"내가 보기엔 이 영화 괜찮아."},"why":"내 생각을 말할 때는 在我看来. 看起来는 겉모습이라 여기엔 안 맞아요."},{"type":"pick","ko":"너 오늘 기분 좋아 보인다.","choices":["你今天看起来很高兴。","你今天很高兴看起来。","你今天看起来高兴很。"],"answer":"你今天看起来很高兴。","full":{"zh":"你今天看起来很高兴。","py":"Nǐ jīntiān kàn qǐlai hěn gāoxìng.","ko":"너 오늘 기분 좋아 보인다."},"why":"看起来는 형용사 앞에 와요. 很도 형용사 앞."}]},{"id":"g32","lv":3,"day":13,"g":["G18","G22"],"title":"才 와 就 — 늦게 vs 일찍","tag":"才 · 就","point":"시간·나이 뒤에 오는 才는 '(생각보다) 늦게, ~가 돼서야'이고, 就는 '(생각보다) 일찍, 벌써'예요. 就 문장은 끝에 보통 了가 붙지만, 才가 '늦게야'일 때는 보통 끝에 了를 붙이지 않아요 (他十点才来了 ✕). 수량 앞의 才는 '겨우, 고작'이라는 뜻이에요 (才五块钱).","pattern":["시간/나이 + 才 + 동사 (늦게야)","시간/나이 + 就 + 동사 + 了 (일찍, 벌써)","才 + 수량 (겨우)"],"ex":[{"zh":"他早上十点才起床。","py":"Tā zǎoshang shí diǎn cái qǐchuáng.","ko":"그는 아침 열 시가 돼서야 일어나."},{"zh":"我六点就到公司了。","py":"Wǒ liù diǎn jiù dào gōngsī le.","ko":"나는 여섯 시에 벌써 회사에 도착했어."},{"zh":"我弟弟才十岁，个子已经很高了。","py":"Wǒ dìdi cái shí suì, gèzi yǐjīng hěn gāo le.","ko":"내 남동생은 겨우 열 살인데 키가 벌써 커."}],"qs":[{"type":"fill","zh":"电影七点开始，他七点半＿＿来。","ko":"영화는 일곱 시에 시작하는데, 그는 일곱 시 반이 돼서야 왔어.","choices":["才","就","再","都"],"answer":"才","full":{"zh":"电影七点开始，他七点半才来。","py":"Diànyǐng qī diǎn kāishǐ, tā qī diǎn bàn cái lái.","ko":"영화는 일곱 시에 시작하는데, 그는 일곱 시 반이 돼서야 왔어."},"why":"'늦게야 왔다'는 시간 + 才 + 동사. 才 문장 끝에는 了가 없어요."},{"type":"pick","ko":"나는 일곱 시에 벌써 일어났어.","choices":["我七点就起床了。","我七点才起床了。","我七点起床就了。"],"answer":"我七点就起床了。","full":{"zh":"我七点就起床了。","py":"Wǒ qī diǎn jiù qǐchuáng le.","ko":"나는 일곱 시에 벌써 일어났어."},"why":"'일찍, 벌써'는 시간 + 就 + 동사 + 了. 才 뒤에는 了를 붙이지 않아요."},{"type":"fill","zh":"我妹妹三岁＿＿会写字了。","ko":"내 여동생은 세 살에 벌써 글자를 쓸 줄 알았어.","choices":["就","才","再","还"],"answer":"就","full":{"zh":"我妹妹三岁就会写字了。","py":"Wǒ mèimei sān suì jiù huì xiě zì le.","ko":"내 여동생은 세 살에 벌써 글자를 쓸 줄 알았어."},"why":"'벌써(이르다)'는 就, 끝의 了와 짝이에요. 才라면 了가 없어야 하고 뜻도 '늦게야'가 돼요."},{"type":"pick","ko":"이 책은 겨우 십 위안이라 싸.","choices":["这本书才十块钱，很便宜。","这本书十块钱才，很便宜。","这本书十块才钱，很便宜。"],"answer":"这本书才十块钱，很便宜。","full":{"zh":"这本书才十块钱，很便宜。","py":"Zhè běn shū cái shí kuài qián, hěn piányi.","ko":"이 책은 겨우 십 위안이라 싸."},"why":"'겨우'의 才는 수량(十块钱) 바로 앞에 와요."}]},{"id":"g25","lv":3,"day":14,"g":["G58","G27"],"title":"把 — 무엇을 어떻게 처리했나","tag":"把字句","point":"'그 물건을 어떻게 했는지' 말할 때 把로 목적어를 동사 앞으로 끌어와요. 把 뒤의 목적어는 보통 이미 아는 그 물건이고, 동사 뒤에는 꼭 뭔가가 더 붙어요: 在/到/给 + 장소·사람, 결과(干净·完), 了 같은 것. ✕ 我把饭吃。(동사 하나로 끝남) 부정 没는 把 앞에 와요 (我没把钱给他).","pattern":["A + 把 + 목적어 + 동사 + 在/到/给 + 장소·사람","A + 把 + 목적어 + 동사 + 결과/방향 + (了)","A + 没 + 把 + 목적어 + 동사 + …"],"ex":[{"zh":"我把书放在桌子上了。","py":"Wǒ bǎ shū fàng zài zhuōzi shang le.","ko":"나 책을 책상 위에 놔뒀어."},{"zh":"你把这本书带给小王吧。","py":"Nǐ bǎ zhè běn shū dài gěi Xiǎo Wáng ba.","ko":"이 책 샤오왕한테 갖다줘."},{"zh":"我把房间打扫干净了。","py":"Wǒ bǎ fángjiān dǎsǎo gānjìng le.","ko":"나 방 깨끗하게 청소했어."}],"qs":[{"type":"fill","zh":"请＿＿门打开。","ko":"문 좀 열어 줘.","choices":["把","被","从","在"],"answer":"把","full":{"zh":"请把门打开。","py":"Qǐng bǎ mén dǎkāi.","ko":"문 좀 열어 줘."},"why":"'문을 열다'처럼 그 물건을 어떻게 하라고 할 때 把 + 물건 + 동사."},{"type":"pick","ko":"나 그 사과 다 먹었어.","choices":["我把那个苹果吃完了。","我把那个苹果吃。","我把吃完了那个苹果。"],"answer":"我把那个苹果吃完了。","full":{"zh":"我把那个苹果吃完了。","py":"Wǒ bǎ nàge píngguǒ chī wán le.","ko":"나 그 사과 다 먹었어."},"why":"把 바로 뒤에 물건, 그다음 동사 + 결과(完). 동사 하나로 끝내면 안 돼요."},{"type":"pick","ko":"나 아직 걔한테 돈 안 갚았어.","choices":["我还没把钱还给他。","我把钱还没还给他。","我还没还给他把钱。"],"answer":"我还没把钱还给他。","full":{"zh":"我还没把钱还给他。","py":"Wǒ hái méi bǎ qián huán gěi tā.","ko":"나 아직 걔한테 돈 안 갚았어."},"why":"没는 把 앞에 와요. 앞의 还는 hái(아직), 뒤의 还는 huán(돌려주다)."},{"type":"fill","zh":"请把这些东西搬＿＿房间里。","ko":"이 물건들 방 안으로 옮겨 줘.","choices":["到","给","着","得"],"answer":"到","full":{"zh":"请把这些东西搬到房间里。","py":"Qǐng bǎ zhèxiē dōngxi bān dào fángjiān li.","ko":"이 물건들 방 안으로 옮겨 줘."},"why":"옮겨서 어떤 곳에 닿게 하는 건 동사 + 到 + 장소."}]},{"id":"g26","lv":3,"day":14,"g":["G59"],"title":"被 — ~에게 당하다","tag":"被字句","point":"주어가 어떤 일을 '당했을' 때 被를 써요. 주어 + 被 + (하는 쪽) + 동사 + 了/결과. 보통 잃어버리거나 혼나는 것처럼 안 좋은 일에 써요. 하는 쪽을 모르면 빼도 돼요 (我的手机被拿走了). 동사 하나로 끝나면 안 되고(✕ 我的书被他拿。), 부정 没는 被 앞에 와요 (没被发现).","pattern":["주어 + 被 + (하는 쪽) + 동사 + 了/결과","주어 + 没 + 被 + (하는 쪽) + 동사"],"ex":[{"zh":"我的手机被小王拿走了。","py":"Wǒ de shǒujī bèi Xiǎo Wáng ná zǒu le.","ko":"내 휴대폰 샤오왕이 가져가 버렸어."},{"zh":"我的面包被狗吃了。","py":"Wǒ de miànbāo bèi gǒu chī le.","ko":"내 빵 개가 먹어 버렸어."},{"zh":"弟弟被妈妈发现了。","py":"Dìdi bèi māma fāxiàn le.","ko":"남동생이 엄마한테 들켰어."}],"qs":[{"type":"fill","zh":"我的书＿＿弟弟拿走了。","ko":"내 책 남동생이 가져가 버렸어.","choices":["被","把","从","对"],"answer":"被","full":{"zh":"我的书被弟弟拿走了。","py":"Wǒ de shū bèi dìdi ná zǒu le.","ko":"내 책 남동생이 가져가 버렸어."},"why":"책이 '당한' 쪽이라 被 + 하는 쪽(弟弟) + 동사."},{"type":"pick","ko":"내 우유 고양이가 마셔 버렸어.","choices":["我的牛奶被猫喝了。","我的牛奶被猫喝。","猫被我的牛奶喝了。"],"answer":"我的牛奶被猫喝了。","full":{"zh":"我的牛奶被猫喝了。","py":"Wǒ de niúnǎi bèi māo hē le.","ko":"내 우유 고양이가 마셔 버렸어."},"why":"당한 것(牛奶)이 주어, 被 뒤에 하는 쪽(猫). 동사 뒤에 了가 있어야 해요."},{"type":"pick","ko":"그 일은 엄마한테 안 들켰어.","choices":["那件事没被妈妈发现。","那件事被妈妈没发现。","那件事不被妈妈发现了。"],"answer":"那件事没被妈妈发现。","full":{"zh":"那件事没被妈妈发现。","py":"Nà jiàn shì méi bèi māma fāxiàn.","ko":"그 일은 엄마한테 안 들켰어."},"why":"부정 没는 被 앞에 와요. 没가 있으면 了는 안 붙여요."},{"type":"fill","zh":"我的面条儿被他吃＿＿了。","ko":"내 국수 걔가 다 먹어 버렸어.","choices":["完","得","着","地"],"answer":"完","full":{"zh":"我的面条儿被他吃完了。","py":"Wǒ de miàntiáor bèi tā chī wán le.","ko":"내 국수 걔가 다 먹어 버렸어."},"why":"'다 먹었다'는 결과 完을 동사 뒤에 붙여요."}]},{"id":"g29","lv":3,"day":16,"g":["G52"],"title":"방향보어 확장 — 想起·笑起来·说下去","tag":"趋向补语的引申用法","point":"방향을 말하던 말이 동사 뒤에서 다른 뜻으로도 쓰여요. 出는 없던 걸 만들어 냄(想出 생각해 내다), 起来는 떠오름(想起来 생각나다)이나 '~하기 시작함'(笑起来 웃기 시작하다), 下는 내려놓음(放下), 下来는 남겨 둠(写下来 적어 두다), 下去는 '계속 ~해 나감'(说下去 계속 말하다)이에요. 起来는 시작, 下去는 계속 — 헷갈리지 마세요.","pattern":["동사 + 出 / 下 (생각해 내다 · 내려놓다)","동사 + 起来 (생각나다 · ~하기 시작하다)","동사 + 下去 (계속 ~하다) · 동사 + 下来 (적어 두다)"],"ex":[{"zh":"我想起来了，他叫小李。","py":"Wǒ xiǎng qilai le, tā jiào Xiǎo Lǐ.","ko":"생각났다, 걔 이름 샤오리야."},{"zh":"小王说完，大家都笑起来了。","py":"Xiǎo Wáng shuō wán, dàjiā dōu xiào qilai le.","ko":"샤오왕이 말을 끝내자 다들 웃기 시작했어."},{"zh":"你放下手机，先吃饭吧。","py":"Nǐ fàng xia shǒujī, xiān chī fàn ba.","ko":"휴대폰 내려놓고 밥부터 먹어."}],"qs":[{"type":"fill","zh":"我想＿＿了一个好办法。","ko":"나 좋은 방법 하나 생각해 냈어.","choices":["出","下","去","上"],"answer":"出","full":{"zh":"我想出了一个好办法。","py":"Wǒ xiǎng chū le yí ge hǎo bànfǎ.","ko":"나 좋은 방법 하나 생각해 냈어."},"why":"없던 생각을 만들어 내는 건 想出."},{"type":"pick","ko":"아이가 갑자기 울기 시작했어.","choices":["孩子突然哭起来了。","孩子突然哭下去了。","孩子突然哭下来了。"],"answer":"孩子突然哭起来了。","full":{"zh":"孩子突然哭起来了。","py":"Háizi tūrán kū qilai le.","ko":"아이가 갑자기 울기 시작했어."},"why":"'~하기 시작하다'는 동사 + 起来. 下去는 '계속'이라 突然과 안 맞아요."},{"type":"fill","zh":"汉语很有意思，我要一直学＿＿。","ko":"중국어 재밌어, 나 계속 배워 나갈 거야.","choices":["下去","起来","下来","出来"],"answer":"下去","full":{"zh":"汉语很有意思，我要一直学下去。","py":"Hànyǔ hěn yǒu yìsi, wǒ yào yìzhí xué xiaqu.","ko":"중국어 재밌어, 나 계속 배워 나갈 거야."},"why":"지금 하던 걸 앞으로 계속하는 건 동사 + 下去."},{"type":"pick","ko":"선생님이 말한 거 적어 둬.","choices":["你把老师说的写下来。","你把老师说的写下去。","你把老师说的下来写。"],"answer":"你把老师说的写下来。","full":{"zh":"你把老师说的写下来。","py":"Nǐ bǎ lǎoshī shuō de xiě xialai.","ko":"선생님이 말한 거 적어 둬."},"why":"적어서 남겨 두는 건 写下来. 写下去는 '계속 써 나가다'라 뜻이 달라요."}]},{"id":"g30","lv":3,"day":16,"g":["G54","G64"],"title":"정도 표현 — 极了·得很·说得很好","tag":"程度补语","point":"형용사 뒤에 极了를 붙이면 '정말 ~하다', 得很을 붙이면 '아주 ~하다'예요 (好极了, 贵得很). 坏了를 붙이면 '~해 죽겠다'처럼 정도가 아주 심하다는 뜻이에요. 累坏了·忙坏了처럼 힘든 상태에 많이 쓰고, 高兴坏了처럼 좋은 일에도 써요. 동사 + 得 + 평가에서 목적어가 있으면 동사를 한 번 더 써요: 他说汉语说得很好. 앞 동사는 빼도 돼요 (他汉语说得很好). ✕ 他说汉语得很好.","pattern":["형용사 + 极了 / 得很","형용사 + 坏了 (累坏了 · 急坏了)","동사 + 목적어 + 동사 + 得 + 평가 = 목적어 + 동사 + 得 + 평가"],"ex":[{"zh":"这个菜好吃极了！","py":"Zhège cài hǎochī jí le!","ko":"이 요리 진짜 맛있다!"},{"zh":"找不到孩子，妈妈急坏了。","py":"Zhǎo bu dào háizi, māma jí huài le.","ko":"아이를 못 찾아서 엄마가 속이 타 죽을 지경이었어."},{"zh":"她唱歌唱得很好。","py":"Tā chàng gē chàng de hěn hǎo.","ko":"걔 노래 진짜 잘 불러."}],"qs":[{"type":"fill","zh":"今天天气好＿＿了！","ko":"오늘 날씨 진짜 좋다!","choices":["极","很","得","坏"],"answer":"极","full":{"zh":"今天天气好极了！","py":"Jīntiān tiānqì hǎo jí le!","ko":"오늘 날씨 진짜 좋다!"},"why":"형용사 + 极了 = 정말 ~하다."},{"type":"pick","ko":"걔 중국어 진짜 잘해.","choices":["他说汉语说得很好。","他说汉语得很好。","他说得汉语很好。"],"answer":"他说汉语说得很好。","full":{"zh":"他说汉语说得很好。","py":"Tā shuō Hànyǔ shuō de hěn hǎo.","ko":"걔 중국어 진짜 잘해."},"why":"목적어(汉语)가 있으면 동사를 한 번 더 쓰고 그 뒤에 得."},{"type":"fill","zh":"这儿的东西贵＿＿。","ko":"여기 물건 엄청 비싸.","choices":["得很","极","很得","坏"],"answer":"得很","full":{"zh":"这儿的东西贵得很。","py":"Zhèr de dōngxi guì de hěn.","ko":"여기 물건 엄청 비싸."},"why":"형용사 + 得很 = 아주 ~하다. 极는 了와 같이 써야 해요."},{"type":"pick","ko":"요 며칠 나 바빠 죽는 줄 알았어.","choices":["这几天我忙坏了。","这几天我坏忙了。","这几天我忙得坏了。"],"answer":"这几天我忙坏了。","full":{"zh":"这几天我忙坏了。","py":"Zhè jǐ tiān wǒ máng huài le.","ko":"요 며칠 나 바빠 죽는 줄 알았어."},"why":"'~해 죽겠다'는 형용사 바로 뒤에 坏了. 得는 넣지 않아요."}]},{"id":"g34","lv":3,"day":16,"g":["G61"],"title":"비교 2 — 更·跟…一样·比…早来十分钟","tag":"比较句","point":"A比B 문장에서 '더'를 넣고 싶으면 형용사 앞에 更이나 还를 써요 (很·非常은 안 돼요). 'A는 B와 같다'는 A跟B一样, '똑같이 ~하다'는 A跟B一样 + 형용사예요. A不比B + 형용사는 'A가 B보다 더 ~한 건 아니다'예요. 얼마나 일찍·많이 했는지는 比B 뒤에 早·多 + 동사 + 수량으로 말해요 (他比我早来了十分钟, 他比我十分钟早来 ✕).","pattern":["A + 比 + B + 更/还 + 형용사","A + 跟 + B + 一样 (+ 형용사)","A + 不比 + B + 형용사","A + 比 + B + 早/晚/多/少 + 동사 + 수량"],"ex":[{"zh":"今天比昨天还冷。","py":"Jīntiān bǐ zuótiān hái lěng.","ko":"오늘은 어제보다 더 추워."},{"zh":"我的手机跟你的一样。","py":"Wǒ de shǒujī gēn nǐ de yíyàng.","ko":"내 휴대폰은 네 거랑 똑같아."},{"zh":"他比我早来了十分钟。","py":"Tā bǐ wǒ zǎo lái le shí fēnzhōng.","ko":"그는 나보다 십 분 일찍 왔어."}],"qs":[{"type":"fill","zh":"这个问题比那个＿＿简单。","ko":"이 문제는 저것보다 더 쉬워.","choices":["更","很","非常","太"],"answer":"更","full":{"zh":"这个问题比那个更简单。","py":"Zhège wèntí bǐ nàge gèng jiǎndān.","ko":"이 문제는 저것보다 더 쉬워."},"why":"比 문장에서 '더'는 更(또는 还). 很·非常·太는 쓸 수 없어요."},{"type":"pick","ko":"나는 형이랑 키가 똑같아.","choices":["我跟哥哥一样高。","我跟哥哥高一样。","我一样跟哥哥高。"],"answer":"我跟哥哥一样高。","full":{"zh":"我跟哥哥一样高。","py":"Wǒ gēn gēge yíyàng gāo.","ko":"나는 형이랑 키가 똑같아."},"why":"A + 跟 + B + 一样 + 형용사. 一样이 형용사 앞에 와요."},{"type":"fill","zh":"我比他多喝了＿＿杯咖啡。","ko":"나는 그보다 커피를 두 잔 더 마셨어.","choices":["两","二","很","更"],"answer":"两","full":{"zh":"我比他多喝了两杯咖啡。","py":"Wǒ bǐ tā duō hē le liǎng bēi kāfēi.","ko":"나는 그보다 커피를 두 잔 더 마셨어."},"why":"'더 많이 했다'는 比B + 多 + 동사 + 수량. 양사 앞의 '둘'은 两이에요."},{"type":"pick","ko":"이 식당이 저 식당보다 더 비싼 건 아니야.","choices":["这个饭馆不比那个贵。","这个饭馆比那个不贵。","这个饭馆不比那个很贵。"],"answer":"这个饭馆不比那个贵。","full":{"zh":"这个饭馆不比那个贵。","py":"Zhège fànguǎn bù bǐ nàge guì.","ko":"이 식당이 저 식당보다 더 비싼 건 아니야."},"why":"부정은 比 앞에 不를 붙여 A + 不比 + B + 형용사. 형용사 앞에 很은 안 붙여요."}]},{"id":"g35","lv":3,"day":16,"g":["G44","G37"],"title":"越…越 · 越来越 — 점점 더","tag":"越…越…","point":"越A越B는 'A할수록 더 B하다'예요 (越吃越喜欢). 越来越 + 형용사는 '점점 더 ~해진다'이고, 끝에 了가 자주 붙어요. 喜欢 같은 마음을 나타내는 동사도 쓸 수 있어요 (越来越喜欢). 越 뒤의 형용사에는 很·非常을 붙이지 않아요 (越来越很冷 ✕, 很越来越冷 ✕).","pattern":["越 + A + 越 + B (A할수록 B)","주어 + 越来越 + 형용사 / 喜欢 같은 동사 (+ 了)"],"ex":[{"zh":"天气越来越冷了。","py":"Tiānqì yuè lái yuè lěng le.","ko":"날씨가 점점 추워져."},{"zh":"这个菜我越吃越喜欢。","py":"Zhège cài wǒ yuè chī yuè xǐhuan.","ko":"이 요리는 먹을수록 좋아져."},{"zh":"他的汉语越来越好了。","py":"Tā de Hànyǔ yuè lái yuè hǎo le.","ko":"그 사람 중국어가 점점 좋아지고 있어."}],"qs":[{"type":"fill","zh":"雨＿＿下越大。","ko":"비가 내릴수록 점점 세져.","choices":["越","更","很","还"],"answer":"越","full":{"zh":"雨越下越大。","py":"Yǔ yuè xià yuè dà.","ko":"비가 내릴수록 점점 세져."},"why":"'A할수록 B'는 越A越B, 越가 두 번 나와요."},{"type":"pick","ko":"요즘 점점 더 바빠.","choices":["最近越来越忙了。","最近越来越很忙了。","最近很越来越忙了。"],"answer":"最近越来越忙了。","full":{"zh":"最近越来越忙了。","py":"Zuìjìn yuè lái yuè máng le.","ko":"요즘 점점 더 바빠."},"why":"越来越 앞뒤에 很을 붙이지 않아요."},{"type":"fill","zh":"他越说越＿＿。","ko":"그는 말할수록 더 화를 냈어.","choices":["生气","很生气","更生气","非常生气"],"answer":"生气","full":{"zh":"他越说越生气。","py":"Tā yuè shuō yuè shēngqì.","ko":"그는 말할수록 더 화를 냈어."},"why":"越 자체가 '더'라서 뒤에 很·更·非常을 또 붙이지 않아요."},{"type":"pick","ko":"나는 중국 음식이 점점 더 좋아져.","choices":["我越来越喜欢中国菜了。","我喜欢越来越中国菜了。","我越来越很喜欢中国菜了。"],"answer":"我越来越喜欢中国菜了。","full":{"zh":"我越来越喜欢中国菜了。","py":"Wǒ yuè lái yuè xǐhuan Zhōngguó cài le.","ko":"나는 중국 음식이 점점 더 좋아져."},"why":"越来越는 喜欢 앞에 오고, 很은 붙이지 않아요."}]},{"id":"g37","lv":3,"day":17,"g":["G72","G31"],"title":"~라면 — 如果…就 · …的话","tag":"假设复句","point":"'만약 A라면 B'는 如果 A，就 B예요. 就는 뒤 문장의 동사 앞에 오고, 뒤 문장에 주어가 있으면 주어 뒤에 써요 (如果下雨，就我们不去 ✕ → 我们就不去 ✓). A 뒤에 的话만 붙여도 '~라면'이 되고, 如果…的话처럼 둘을 같이 써도 돼요. 就는 빼도 될 때가 많아요.","pattern":["如果 + A，(주어) + 就 + B","A + 的话，(주어) + 就 + B","如果 + A + 的话，(주어) + 就 + B"],"ex":[{"zh":"如果明天下雨，我们就不去了。","py":"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le.","ko":"내일 비 오면 우리 안 갈래."},{"zh":"你忙的话，我自己去。","py":"Nǐ máng dehuà, wǒ zìjǐ qù.","ko":"너 바쁘면 나 혼자 갈게."},{"zh":"如果你有时间的话，就来我家玩吧。","py":"Rúguǒ nǐ yǒu shíjiān dehuà, jiù lái wǒ jiā wán ba.","ko":"시간 있으면 우리 집에 놀러 와."}],"qs":[{"type":"fill","zh":"如果你累了，＿＿先休息吧。","ko":"피곤하면 먼저 쉬어.","choices":["就","才","也","都"],"answer":"就","full":{"zh":"如果你累了，就先休息吧。","py":"Rúguǒ nǐ lèi le, jiù xiān xiūxi ba.","ko":"피곤하면 먼저 쉬어."},"why":"如果 A，就 B — '~라면 (그럼) ~해'. 여기서 '그럼'을 이어 주는 말은 就예요."},{"type":"pick","ko":"내일 시간 있으면 내가 너 찾아갈게.","choices":["如果明天有时间，我就去找你。","如果明天有时间，就我去找你。","明天有时间如果，我就去找你。"],"answer":"如果明天有时间，我就去找你。","full":{"zh":"如果明天有时间，我就去找你。","py":"Rúguǒ míngtiān yǒu shíjiān, wǒ jiù qù zhǎo nǐ.","ko":"내일 시간 있으면 내가 너 찾아갈게."},"why":"就는 주어(我) 뒤, 동사 앞이에요. 如果는 문장 맨 앞이나 주어 바로 뒤에 와요."},{"type":"fill","zh":"你不想去＿＿，就别去了。","ko":"가기 싫으면 가지 마.","choices":["的话","如果","因为","虽然"],"answer":"的话","full":{"zh":"你不想去的话，就别去了。","py":"Nǐ bù xiǎng qù dehuà, jiù bié qù le.","ko":"가기 싫으면 가지 마."},"why":"조건 뒤에 붙는 건 的话예요. 如果·因为·虽然은 앞에 와요."},{"type":"pick","ko":"너무 비싸면 나 안 살래.","choices":["如果太贵的话，我就不买了。","如果太贵的话，就我不买了。","因为太贵的话，我就不买了。"],"answer":"如果太贵的话，我就不买了。","full":{"zh":"如果太贵的话，我就不买了。","py":"Rúguǒ tài guì dehuà, wǒ jiù bù mǎi le.","ko":"너무 비싸면 나 안 살래."},"why":"如果와 的话는 같이 써도 돼요. 就는 주어 뒤에, 的话는 因为와 짝이 아니에요."}]},{"id":"g40","lv":3,"day":17,"g":["G29","G66"],"title":"또는 — 或者 와 还是","tag":"或者·还是","point":"'A 또는 B'는 보통 그냥 말하는 문장에서는 或者, '어느 쪽이야?'를 묻는 문장에서는 还是를 써요 (1·2급에서 배운 'A야, 아니면 B야?'). 我不知道…还是…처럼 어느 쪽인지 모를 때도 还是를 써요. 我们星期六或者星期天去吧 (둘 중 아무 때나) / 你今天去还是明天去？(어느 쪽인지 물음). 或者 A，或者 B처럼 두 번 써서 '~하거나 ~하거나'라고도 해요. 或는 或者와 같은 뜻인데 주로 글에서 써요.","pattern":["A + 或者 + B (말하는 문장)","A + 还是 + B？ (묻는 문장)","或者 + A，或者 + B"],"ex":[{"zh":"我们星期六或者星期天去吧。","py":"Wǒmen xīngqīliù huòzhě xīngqītiān qù ba.","ko":"우리 토요일이나 일요일에 가자."},{"zh":"你想吃米饭还是饺子？","py":"Nǐ xiǎng chī mǐfàn háishi jiǎozi?","ko":"밥 먹을래, 아니면 만두 먹을래?"},{"zh":"周末我或者在家看书，或者出去看电影。","py":"Zhōumò wǒ huòzhě zài jiā kàn shū, huòzhě chūqù kàn diànyǐng.","ko":"주말엔 집에서 책을 읽거나 나가서 영화를 봐."}],"qs":[{"type":"fill","zh":"你今天去＿＿明天去？","ko":"너 오늘 가, 아니면 내일 가?","choices":["还是","或者","和","跟"],"answer":"还是","full":{"zh":"你今天去还是明天去？","py":"Nǐ jīntiān qù háishi míngtiān qù?","ko":"너 오늘 가, 아니면 내일 가?"},"why":"둘 중 하나를 고르라고 묻는 문장에는 还是예요."},{"type":"fill","zh":"我周末在家看书＿＿看电视。","ko":"나는 주말에 집에서 책을 보거나 TV를 봐.","choices":["或者","还是","但是","所以"],"answer":"或者","full":{"zh":"我周末在家看书或者看电视。","py":"Wǒ zhōumò zài jiā kàn shū huòzhě kàn diànshì.","ko":"나는 주말에 집에서 책을 보거나 TV를 봐."},"why":"묻는 문장이 아니면 '~거나'는 或者예요."},{"type":"pick","ko":"주말에 나는 영화 보러 가거나 친구 집에 놀러 가.","choices":["周末我或者去看电影，或者去朋友家玩。","周末我还是去看电影，还是去朋友家玩。","周末我或者去看电影，还是去朋友家玩。"],"answer":"周末我或者去看电影，或者去朋友家玩。","full":{"zh":"周末我或者去看电影，或者去朋友家玩。","py":"Zhōumò wǒ huòzhě qù kàn diànyǐng, huòzhě qù péngyou jiā wán.","ko":"주말에 나는 영화 보러 가거나 친구 집에 놀러 가."},"why":"그냥 말하는 문장이니 或者 A，或者 B. 还是는 물을 때 써요."},{"type":"pick","ko":"이 책 네 거야, 아니면 샤오왕 거야?","choices":["这本书是你的还是小王的？","这本书是你的或者小王的？","这本书是你的还是小王的吗？"],"answer":"这本书是你的还是小王的？","full":{"zh":"这本书是你的还是小王的？","py":"Zhè běn shū shì nǐ de háishi Xiǎo Wáng de?","ko":"이 책 네 거야, 아니면 샤오왕 거야?"},"why":"고르라고 묻는 말은 还是이고, 还是 질문에는 吗를 붙이지 않아요."}]},{"id":"g41","lv":3,"day":17,"g":["G40"],"title":"除了 — ~말고도 / ~만 빼고","tag":"除了","point":"除了 A，还/也 B = A 말고도 B도 해요 (A에 B를 더해요). 除了 A，都 B = A만 빼고 다 B해요 (A를 빼요). 뜻은 뒤에 还·也가 오는지 都가 오는지로 정해져요.","pattern":["除了 + A，(주어) + 还/也 + B","除了 + A，(주어) + 都 + B"],"ex":[{"zh":"她除了唱歌，还喜欢跳舞。","py":"Tā chúle chàng gē, hái xǐhuan tiàowǔ.","ko":"그녀는 노래 부르는 것 말고 춤추는 것도 좋아해."},{"zh":"除了星期天，我每天都上班。","py":"Chúle xīngqītiān, wǒ měi tiān dōu shàngbān.","ko":"나는 일요일 빼고 매일 출근해."},{"zh":"除了咖啡，我也爱喝茶。","py":"Chúle kāfēi, wǒ yě ài hē chá.","ko":"나는 커피 말고 차도 좋아해."}],"qs":[{"type":"fill","zh":"除了小李，大家＿＿来了。","ko":"샤오리 빼고 다 왔어.","choices":["都","才","再","很"],"answer":"都","full":{"zh":"除了小李，大家都来了。","py":"Chúle Xiǎo Lǐ, dàjiā dōu lái le.","ko":"샤오리 빼고 다 왔어."},"why":"'A만 빼고 다'는 除了 A，都 B."},{"type":"pick","ko":"나는 축구 말고 농구도 해.","choices":["除了踢足球，我还打篮球。","除了踢足球，我都打篮球。","除了踢足球，还我打篮球。"],"answer":"除了踢足球，我还打篮球。","full":{"zh":"除了踢足球，我还打篮球。","py":"Chúle tī zúqiú, wǒ hái dǎ lánqiú.","ko":"나는 축구 말고 농구도 해."},"why":"'A 말고 B도'는 除了 A，还 B. 还는 주어(我) 뒤에 와요."},{"type":"fill","zh":"＿＿妈妈，我们都爱吃鱼。","ko":"엄마 빼고 우리는 다 생선을 좋아해.","choices":["除了","因为","虽然","如果"],"answer":"除了","full":{"zh":"除了妈妈，我们都爱吃鱼。","py":"Chúle māma, wǒmen dōu ài chī yú.","ko":"엄마 빼고 우리는 다 생선을 좋아해."},"why":"'~만 빼고'는 除了예요. 뒤의 都와 짝을 이뤄요."},{"type":"pick","ko":"토요일 말고 일요일에도 나 시간 있어.","choices":["除了星期六，星期天我也有时间。","除了星期六，星期天我都有时间。","除了星期六，星期天也我有时间。"],"answer":"除了星期六，星期天我也有时间。","full":{"zh":"除了星期六，星期天我也有时间。","py":"Chúle xīngqīliù, xīngqītiān wǒ yě yǒu shíjiān.","ko":"토요일 말고 일요일에도 나 시간 있어."},"why":"'~말고 ~도'(더하기)는 也. 都를 쓰면 '빼고 다'가 돼요. 也는 주어 뒤에 와요."}]},{"id":"g46","lv":3,"day":17,"g":["G24","G25","G26","G74","G28"],"title":"为了·为·向·关于·根据","tag":"介词","point":"为了 + 목적은 '~하려고, ~를 위해서'예요 (为了看这个电影，…). 为 + 사람은 '~를 위해' 또는 '~때문에'예요 (我为你高兴). 向은 '~에게'(向他学习) 또는 '~쪽으로'(向前走)예요. 关于는 '~에 관해'로, 보통 문장 맨 앞(关于这件事，…)이나 명사 앞에 와요. 根据는 '~에 따르면, ~를 바탕으로'예요. 이런 말(개사)은 보통 동사 앞에 와요 (向他学习 ✓ / 学习向他 ✕).","pattern":["为了 + 목적，…","为 + 사람 + 동사/형용사","向 + 사람/방향 + 동사","关于 + 일，…","根据 + 근거，…"],"ex":[{"zh":"为了学好汉语，我每天看中文电影。","py":"Wèile xuéhǎo Hànyǔ, wǒ měi tiān kàn Zhōngwén diànyǐng.","ko":"중국어 잘하려고 나 매일 중국 영화 봐."},{"zh":"你应该向他学习。","py":"Nǐ yīnggāi xiàng tā xuéxí.","ko":"너는 그 사람한테 배워야 해."},{"zh":"关于这件事，我不太清楚。","py":"Guānyú zhè jiàn shì, wǒ bú tài qīngchu.","ko":"이 일에 대해서는 나 잘 몰라."}],"qs":[{"type":"fill","zh":"＿＿看这个电影，我们早上六点就起床了。","ko":"이 영화 보려고 우리 아침 여섯 시에 일어났어.","choices":["为了","关于","根据","向"],"answer":"为了","full":{"zh":"为了看这个电影，我们早上六点就起床了。","py":"Wèile kàn zhège diànyǐng, wǒmen zǎoshang liù diǎn jiù qǐchuáng le.","ko":"이 영화 보려고 우리 아침 여섯 시에 일어났어."},"why":"목적 '~하려고'는 为了."},{"type":"pick","ko":"앞으로 쭉 가.","choices":["一直向前走。","一直前向走。","向一直前走。"],"answer":"一直向前走。","full":{"zh":"一直向前走。","py":"Yìzhí xiàng qián zǒu.","ko":"앞으로 쭉 가."},"why":"向 + 방향 + 동사. 向과 前은 붙어 있어야 해요."},{"type":"fill","zh":"＿＿朋友的介绍，我买了这本书。","ko":"친구가 소개해 준 걸 듣고 이 책을 샀어.","choices":["根据","为了","向","关于"],"answer":"根据","full":{"zh":"根据朋友的介绍，我买了这本书。","py":"Gēnjù péngyou de jièshào, wǒ mǎi le zhè běn shū.","ko":"친구가 소개해 준 걸 듣고 이 책을 샀어."},"why":"무엇을 바탕으로 할 때는 根据."},{"type":"pick","ko":"너 잘돼서 나도 정말 기뻐.","choices":["我真为你高兴。","我真高兴为你。","我为真你高兴。"],"answer":"我真为你高兴。","full":{"zh":"我真为你高兴。","py":"Wǒ zhēn wèi nǐ gāoxìng.","ko":"너 잘돼서 나도 정말 기뻐."},"why":"为 + 사람은 형용사·동사 앞에 와요. 真은 为 앞."}]},{"id":"g47","lv":3,"day":22,"g":["G60","G62"],"title":"~한 채로 · 어디에 무엇이 나타나다","tag":"着·存现句","point":"동사1 + 着 + 동사2는 '~한 채로 ~하다, ~하면서 ~하다'예요. 앞 동작이 뒤 동작의 모습을 말해 줘요 (笑着说 웃으면서 말하다, 坐着吃 앉아서 먹다). 어떤 곳에 사람·물건이 나타나거나 사라질 때는 장소 + 동사 + 了/来·过来 + 수량 + 사람·물건 순서로 말해요 (前面走过来一个人). 이때 나오는 사람·물건은 처음 나타난 '어떤' 것이라 보통 一个 같은 수량을 붙이고, 这个·那个는 쓰지 않아요 (前面走过来这个人 ✕).","pattern":["동사1 + 着 + 동사2","장소 + 동사 + 了/来/过来 + 수량 + 사람·물건"],"ex":[{"zh":"他每天走着去学校。","py":"Tā měi tiān zǒu zhe qù xuéxiào.","ko":"그는 매일 걸어서 학교에 가."},{"zh":"我们班新来了一个同学。","py":"Wǒmen bān xīn lái le yí ge tóngxué.","ko":"우리 반에 친구가 한 명 새로 왔어."},{"zh":"前面走过来一个人。","py":"Qiánmiàn zǒu guòlai yí ge rén.","ko":"앞에서 어떤 사람이 걸어와."}],"qs":[{"type":"fill","zh":"我们坐＿＿吃吧。","ko":"우리 앉아서 먹자.","choices":["着","了","过","得"],"answer":"着","full":{"zh":"我们坐着吃吧。","py":"Wǒmen zuò zhe chī ba.","ko":"우리 앉아서 먹자."},"why":"'~한 채로 ~하다'는 동사1 + 着 + 동사2."},{"type":"pick","ko":"위층에 한 가족이 이사 왔어.","choices":["楼上搬来了一家人。","一家人搬来了楼上。","楼上搬来了这家人。"],"answer":"楼上搬来了一家人。","full":{"zh":"楼上搬来了一家人。","py":"Lóu shang bān lái le yì jiā rén.","ko":"위층에 한 가족이 이사 왔어."},"why":"장소가 맨 앞, 나타난 사람은 동사 뒤. 처음 나온 사람이라 这家人은 안 돼요."},{"type":"pick","ko":"그는 웃으면서 나한테 고맙다고 했어.","choices":["他笑着对我说谢谢。","他着笑对我说谢谢。","他对我说笑着谢谢。"],"answer":"他笑着对我说谢谢。","full":{"zh":"他笑着对我说谢谢。","py":"Tā xiào zhe duì wǒ shuō xièxie.","ko":"그는 웃으면서 나한테 고맙다고 했어."},"why":"着는 앞 동작(笑) 바로 뒤에 붙고, 그 뒤에 본 동작(说)이 와요."},{"type":"fill","zh":"前面跑过来＿＿狗。","ko":"앞에서 웬 개 한 마리가 뛰어와.","choices":["一只","这只","那只","一点儿"],"answer":"一只","full":{"zh":"前面跑过来一只狗。","py":"Qiánmiàn pǎo guòlai yì zhī gǒu.","ko":"앞에서 웬 개 한 마리가 뛰어와."},"why":"나타난 것은 처음 나온 '어떤' 것이라 一 + 양사를 붙여요. 这只·那只는 안 돼요."}]},{"id":"g48","lv":3,"day":23,"g":["G05"],"title":"떨어지는 동사 — 见面 · 结婚 · 洗澡","tag":"离合词","point":"见面·结婚·洗澡·帮忙은 '동사 + 목적어'가 붙어서 된 말(이합사)이라 뒤에 또 사람을 붙이지 않아요 (见面他 ✕, 结婚他 ✕). 상대는 跟 + 사람으로 앞에 써요 (跟他见面, 跟他结婚). 了는 뒤에 붙여도 돼요 (他结婚了). 하지만 횟수나 个가 들어가면 두 글자 사이에 넣어요 (见了一次面, 洗个澡, 帮了我一个忙). 过도 사이에 넣어요 (见过面).","pattern":["跟 + 사람 + 见面/结婚","见 + 了/过 + 횟수 + 面","帮 + 사람 + 一个忙 · 洗个澡"],"ex":[{"zh":"我明天跟朋友见面。","py":"Wǒ míngtiān gēn péngyou jiànmiàn.","ko":"나 내일 친구 만나."},{"zh":"他帮了我一个忙。","py":"Tā bāng le wǒ yí ge máng.","ko":"걔가 나를 도와줬어."},{"zh":"我一回家就洗澡。","py":"Wǒ yì huí jiā jiù xǐzǎo.","ko":"나는 집에 오자마자 씻어."}],"qs":[{"type":"fill","zh":"我下午要＿＿王老师见面。","ko":"나 오후에 왕 선생님 만나야 해.","choices":["跟","见","给","让"],"answer":"跟","full":{"zh":"我下午要跟王老师见面。","py":"Wǒ xiàwǔ yào gēn Wáng lǎoshī jiànmiàn.","ko":"나 오후에 왕 선생님 만나야 해."},"why":"见面 뒤에는 사람을 못 붙여요. 跟 + 사람 + 见面."},{"type":"pick","ko":"그는 작년에 그녀와 결혼했어.","choices":["他去年跟她结婚了。","他去年结婚她了。","他去年结婚跟她了。"],"answer":"他去年跟她结婚了。","full":{"zh":"他去年跟她结婚了。","py":"Tā qùnián gēn tā jiéhūn le.","ko":"그는 작년에 그녀와 결혼했어."},"why":"结婚 뒤에 사람 ✕. 跟 + 사람을 结婚 앞에."},{"type":"fill","zh":"我们见＿＿两次面。","ko":"우리 두 번 만났어.","choices":["了","着","得","的"],"answer":"了","full":{"zh":"我们见了两次面。","py":"Wǒmen jiàn le liǎng cì miàn.","ko":"우리 두 번 만났어."},"why":"了와 횟수는 见과 面 사이에 들어가요."},{"type":"pick","ko":"나 좀 도와줄 수 있어?","choices":["你能帮我一个忙吗？","你能帮忙我吗？","你能帮一个忙我吗？"],"answer":"你能帮我一个忙吗？","full":{"zh":"你能帮我一个忙吗？","py":"Nǐ néng bāng wǒ yí ge máng ma?","ko":"나 좀 도와줄 수 있어?"},"why":"帮忙 뒤에 사람 ✕. 사람은 帮과 忙 사이에 넣어요 (帮我一个忙)."}]},{"id":"g49","lv":3,"day":23,"g":["G15","G34","G76"],"title":"겹쳐 말하기와 대략의 수 — 个个·一个一个·三四个","tag":"量词重叠 · 概数","point":"양사를 겹치면(个个·件件) '하나하나 다, 모두'라는 뜻이라 보통 都와 같이 써요 (他们个个都很高). 一个一个(地) + 동사는 '하나씩 차례로'예요. 이웃한 두 숫자를 이어 말하면 대략의 수가 돼요 (三四个 = 서너 개, 七八岁 = 일고여덟 살). 이때 사이에 和를 넣지 않아요 (三和四个 ✕). 大概 + 수도 '대략 ~쯤'이에요.","pattern":["양사 겹치기(个个·件件) + 都 … (하나하나 다)","一 + 양사 + 一 + 양사 (+ 地) + 동사 (하나씩)","이웃 숫자 + 양사 (三四个 · 七八岁)","大概 + 수 + 양사"],"ex":[{"zh":"这些学生个个都很认真。","py":"Zhèxiē xuésheng gègè dōu hěn rènzhēn.","ko":"이 학생들은 하나같이 다 성실해."},{"zh":"请大家一个一个地进来。","py":"Qǐng dàjiā yí ge yí ge de jìnlai.","ko":"다들 한 명씩 들어와."},{"zh":"那个孩子大概七八岁。","py":"Nàge háizi dàgài qī bā suì.","ko":"그 아이는 일고여덟 살쯤 됐어."}],"qs":[{"type":"fill","zh":"这些苹果个个＿＿很好吃。","ko":"이 사과들은 하나같이 다 맛있어.","choices":["都","就","才","再"],"answer":"都","full":{"zh":"这些苹果个个都很好吃。","py":"Zhèxiē píngguǒ gègè dōu hěn hǎochī.","ko":"이 사과들은 하나같이 다 맛있어."},"why":"个个(하나하나 다)는 보통 都와 같이 써요."},{"type":"pick","ko":"학생들이 한 명씩 차례로 들어왔어.","choices":["学生们一个一个地进来了。","学生们一个地一个进来了。","学生们个一个一地进来了。"],"answer":"学生们一个一个地进来了。","full":{"zh":"学生们一个一个地进来了。","py":"Xuéshengmen yí ge yí ge de jìnlai le.","ko":"학생들이 한 명씩 차례로 들어왔어."},"why":"'하나씩'은 一个一个를 붙여 쓰고, 地는 그 뒤, 동사 앞에 와요."},{"type":"fill","zh":"我在超市买了＿＿个苹果。","ko":"나 마트에서 사과 서너 개 샀어.","choices":["三四","三和四","四三","三个四"],"answer":"三四","full":{"zh":"我在超市买了三四个苹果。","py":"Wǒ zài chāoshì mǎi le sān sì ge píngguǒ.","ko":"나 마트에서 사과 서너 개 샀어."},"why":"대략의 수는 작은 수부터 이웃 숫자를 바로 붙여요. 和는 넣지 않아요."},{"type":"pick","ko":"그 선생님은 대략 마흔 살쯤이야.","choices":["那位老师大概四十岁。","那位老师四十岁大概。","那位老师大概岁四十。"],"answer":"那位老师大概四十岁。","full":{"zh":"那位老师大概四十岁。","py":"Nà wèi lǎoshī dàgài sìshí suì.","ko":"그 선생님은 대략 마흔 살쯤이야."},"why":"大概는 수 앞에 오고, 岁는 수 뒤에 와요."}]},{"id":"g50","lv":3,"day":28,"g":["G48","G41"],"title":"범위와 시작 — 在…上/下/中 · 从…起","tag":"在…上/下/中·从…起","point":"在 + 명사 + 上/中/下는 '어떤 면에서·어떤 일을 하는 중에·어떤 도움 속에서'처럼 범위나 조건을 말해요. 在学习上 (공부 면에서), 在工作中 (일하는 중에), 在老师的帮助下 (선생님의 도움으로). 帮助 뒤에는 보통 下를 써요. 从 + 때 + 起는 '그때부터 (쭉)'예요 (从今天起 오늘부터). 从…开始와 비슷한 뜻이에요.","pattern":["在 + 명사 + 上 (~ 면에서)","在 + 명사 + 中 (~하는 중에)","在 + 누구의 帮助 + 下 (~의 도움으로)","从 + 때 + 起 (~부터)"],"ex":[{"zh":"在老师的帮助下，我的汉语水平提高了。","py":"Zài lǎoshī de bāngzhù xià, wǒ de Hànyǔ shuǐpíng tígāo le.","ko":"선생님 도움으로 내 중국어 실력이 늘었어."},{"zh":"从明天起，我每天早上去跑步。","py":"Cóng míngtiān qǐ, wǒ měi tiān zǎoshang qù pǎobù.","ko":"내일부터 나는 매일 아침 달리기하러 갈 거야."},{"zh":"在工作中，他遇到了很多问题。","py":"Zài gōngzuò zhōng, tā yùdào le hěn duō wèntí.","ko":"일하면서 그는 많은 문제를 겪었어."}],"qs":[{"type":"fill","zh":"从今天＿＿，我不喝咖啡了。","ko":"오늘부터 나 커피 안 마셔.","choices":["起","上","中","下"],"answer":"起","full":{"zh":"从今天起，我不喝咖啡了。","py":"Cóng jīntiān qǐ, wǒ bù hē kāfēi le.","ko":"오늘부터 나 커피 안 마셔."},"why":"'~부터'는 从 + 때 + 起."},{"type":"fill","zh":"在大家的帮助＿＿，我很快习惯了这里的生活。","ko":"모두의 도움으로 나는 금방 여기 생활에 익숙해졌어.","choices":["下","上","起","里"],"answer":"下","full":{"zh":"在大家的帮助下，我很快习惯了这里的生活。","py":"Zài dàjiā de bāngzhù xià, wǒ hěn kuài xíguàn le zhèlǐ de shēnghuó.","ko":"모두의 도움으로 나는 금방 여기 생활에 익숙해졌어."},"why":"'~의 도움으로'는 在…的帮助下."},{"type":"pick","ko":"그는 생활 면에서 나를 많이 챙겨 줘.","choices":["他在生活上很照顾我。","他在生活起很照顾我。","他生活在上很照顾我。"],"answer":"他在生活上很照顾我。","full":{"zh":"他在生活上很照顾我。","py":"Tā zài shēnghuó shang hěn zhàogù wǒ.","ko":"그는 생활 면에서 나를 많이 챙겨 줘."},"why":"'~ 면에서'는 在 + 명사 + 上. 起는 从과 짝이에요."},{"type":"pick","ko":"다음 주부터 나는 매일 체육관에 가서 운동할 거야.","choices":["从下个星期起，我每天去体育馆锻炼。","从下个星期上，我每天去体育馆锻炼。","起从下个星期，我每天去体育馆锻炼。"],"answer":"从下个星期起，我每天去体育馆锻炼。","full":{"zh":"从下个星期起，我每天去体育馆锻炼。","py":"Cóng xià ge xīngqī qǐ, wǒ měi tiān qù tǐyùguǎn duànliàn.","ko":"다음 주부터 나는 매일 체육관에 가서 운동할 거야."},"why":"从 + 때 + 起 순서예요. 从과 짝은 上이 아니라 起."}]}];
